const e="newhsk3",t=3,n=[{num:1,title:"我们去机场接你们",points:[{id:"NH3.1.1",name:"固定短语“看上去 / 看起来”",pinyin:"kànshàngqu / kànqǐlái",type:"固定短语",explainEn:"Use 看上去/看起来 to say how someone or something seems or looks.",structure:"主语 + 看上去/看起来 + 形容词/短语",examples:[{zh:"他看起来很年轻。",en:"He looks very young.",py:"Tā kàn qǐ lái hěn nián qīng."},{zh:"这个菜看上去很好吃。",en:"This dish looks delicious.",py:"Zhè ge cài kàn shàng qù hěn hǎo chī."},{zh:"你今天看起来有点儿累。",en:"You look a little tired today.",py:"Nǐ jīn tiān kàn qǐ lái yǒu diǎnr lèi."}],exercises:[{kind:"choice",q:"这件衣服___很贵，你在哪儿买的？",instr:"辨析",instrEn:"Pick the right one",body:"这件衣服___很贵，你在哪儿买的？",options:["看起来","看出来","看见","看到"],answer:0,explain:"“看起来”说外表给人的印象，后面可以直接接形容词；“看见、看到、看出来”是动作或结果，不能这样用。",explainEn:"看起来 tells how something seems from its look and can take an adjective; 看见/看到/看出来 are actions and can't."},{kind:"choice",q:"这个包看起来很贵，___。",instr:"完成",instrEn:"Complete the sentence",body:"这个包看起来很贵，___。",options:["所以只要五十块","其实只要五十块","因为只要五十块","而且只要五十块"],answer:1,explain:"“看起来”只说从外表看到的样子，常跟“其实”一起说真实情况；“所以、因为、而且”跟前面“看起来贵”接不上。",explainEn:'看起来 is only how something looks, so it often pairs with 其实 to give the real fact; 所以/因为/而且 do not connect "looks expensive" with "only 50 yuan".'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这个蛋糕看起来很好吃。","看起来要下雨了。","我看起来他今天很累。","他看上去有点儿着急。"],answer:2,explain:"“看起来”前面的主语是被看的人或东西，应该说“他今天看起来很累”。",explainEn:"The subject of 看起来 is the person being looked at: say 他今天看起来很累."},{q:"翻译：Your new phone looks really nice.",a:"你的新手机看上去很不错。",instr:"翻译",instrEn:"Translate",body:"Your new phone looks really nice."}],note:"“看上去”和“看起来”在表示外表印象时基本可以互换。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Subject + kànshàngqu / kànqǐlái + Adjective/Phrase",noteEn:"看上去 and 看起来 are basically interchangeable for outward impression.",typeEn:"Set phrase"},{id:"NH3.1.2",name:"疑问代词的非疑问用法（1）",pinyin:"yíwèn dàicí de fēi yíwèn yòngfǎ (yī)",type:"代词用法",explainEn:"A question word can mean an unknown or non-specific person, thing, or place in a statement.",structure:"谁 / 什么 / 哪儿 / 哪 + ……（不真正提问）",examples:[{zh:"我好像在哪儿见过他。",en:"I seem to have seen him somewhere.",py:"Wǒ hǎo xiàng zài nǎr jiàn guo tā."},{zh:"我想吃点儿什么。",en:"I want to eat something.",py:"Wǒ xiǎng chī diǎnr shén me."},{zh:"我们找谁问一下吧。",en:"Let us find someone to ask.",py:"Wǒ men zhǎo shéi wèn yí xià ba."}],exercises:[{kind:"choice",q:"门口好像有___在叫你，你去看看吧。",instr:"辨析",instrEn:"Pick the right one",body:"门口好像有___在叫你，你去看看吧。",options:["哪儿","哪个","多少","谁"],answer:3,explain:"这里的“谁”不是提问，表示“某个人”；“哪个”后面要有名词，“哪儿、多少”不能指人。",explainEn:'Here 谁 is not a question; it means "someone". 哪个 needs a noun after it, and 哪儿/多少 cannot refer to a person.'},{kind:"choice",q:"这个歌我好像在哪儿听过，可是___。",instr:"完成",instrEn:"Complete the sentence",body:"这个歌我好像在哪儿听过，可是___。",options:["想不起来是在哪儿了","记得很清楚是在家里","我知道是在电视上","我一下就想起来了"],answer:0,explain:"这里的“哪儿”表示说不清的地方，说话人不记得在哪儿，所以是“想不起来”；说出很清楚的地方就跟“好像在哪儿”矛盾了。",explainEn:'哪儿 here means "somewhere I am not sure of", so the speaker cannot remember; knowing the exact place contradicts 好像在哪儿.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你想喝点儿什么吗？","我的书好像忘在什么了。","周末我不想去哪儿。","我们找谁帮帮忙吧。"],answer:1,explain:"表示不确定的地方要用“哪儿”，应该说“忘在哪儿了”；“什么”不能指地方。",explainEn:"For an unknown place use 哪儿: 忘在哪儿了. 什么 cannot mean a place."},{q:"翻译：I seem to have lost my phone somewhere.",a:"我的手机好像丢在哪儿了。",instr:"翻译",instrEn:"Translate",body:"I seem to have lost my phone somewhere."}],note:"这里的疑问代词不要求对方回答具体的人、事物或地点。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"shéi / shénme / nǎr / nǎ + ... (used as a non-question word)",noteEn:"Here the question word doesn't ask for a specific person/thing/place.",typeEn:"Pronoun usage"},{id:"NH3.1.3",name:"多项定语",pinyin:"duōxiàng dìngyǔ",type:"定语",explainEn:"When several words describe one noun, put them before the noun in a natural order.",structure:"时间/处所 + 动作/状态 + 特点 + 的 + 名词",examples:[{zh:"这是我昨天买的新书。",en:"This is the new book I bought yesterday.",py:"Zhè shì wǒ zuó tiān mǎi de xīn shū."},{zh:"那个穿白衣服的年轻人是我朋友。",en:"That young person in white is my friend.",py:"Nà ge chuān bái yī fu de nián qīng rén shì wǒ péng you."},{zh:"我喜欢那张在北京拍的照片。",en:"I like that photo taken in Beijing.",py:"Wǒ xǐ huan nà zhāng zài běi jīng pāi de zhào piàn."}],exercises:[{kind:"choice",q:"妈妈送给我___。",instr:"辨析",instrEn:"Pick the right one",body:"妈妈送给我___。",options:["一件很漂亮红色的大衣","一件红色的很漂亮大衣","一件很漂亮的红色大衣","一件红色很漂亮大衣"],answer:2,explain:"“很漂亮”做定语后面要加“的”；表示颜色的“红色”直接放在名词前面。",explainEn:"很漂亮 needs 的 before what it describes; the color word 红色 goes right next to the noun."},{kind:"choice",q:"___是我们的新同学。",instr:"完成",instrEn:"Complete the sentence",body:"___是我们的新同学。",options:["站在门口那个的小男孩儿","那个站在门口的小男孩儿","那个小站在门口的男孩儿","那个站在门口小的男孩儿"],answer:1,explain:"“站在门口的”要带“的”放在前面，“小”不带“的”，要紧挨着“男孩儿”；“那个”不能放进“的”前面的短语里。",explainEn:"The phrase 站在门口的 (with 的) comes first, and the bare adjective 小 must sit right next to 男孩儿; 那个 can't go inside the 的 phrase."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["桌子上有一本很有意思新书。","我有一个很热情的中国朋友。","他是我们班最高的男生。","我昨天买的那本书很有意思。"],answer:0,explain:"“很有意思”做定语要加“的”，应该说“一本很有意思的新书”。",explainEn:"很有意思 needs 的 before the noun: 一本很有意思的新书."},{q:"翻译：The new teacher who came today is very young.",a:"今天来的那位新老师很年轻。",instr:"翻译",instrEn:"Translate",body:"The new teacher who came today is very young."}],note:"多项定语的顺序较复杂，本级先掌握常见顺序，不要求一次记住所有规则。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Time/Place + Action/State + Feature + de + Noun",noteEn:"Multiple modifiers are complex; just learn the common order for now.",typeEn:"Attributive"}]},{num:2,title:"你们想吃什么就点什么",points:[{id:"NH3.2.1",name:"并列复句“又……又……”",pinyin:"yòu ... yòu ...",type:"并列复句",explainEn:"Use 又…又… to say two qualities or actions are both true.",structure:"又 + 形容词/动词 + 又 + 形容词/动词",examples:[{zh:"这个菜又便宜又好吃。",en:"This dish is cheap and delicious.",py:"Zhè ge cài yòu pián yi yòu hǎo chī."},{zh:"这个小区又干净又安静。",en:"This neighborhood is clean and quiet.",py:"Zhè ge xiǎo qū yòu gān jìng yòu ān jìng."},{zh:"他又高又瘦。",en:"He is tall and thin.",py:"Tā yòu gāo yòu shòu."}],exercises:[{kind:"choice",q:"这个房间又大___干净，我很满意。",instr:"辨析",instrEn:"Pick the right one",body:"这个房间又大___干净，我很满意。",options:["也","又","很","和"],answer:1,explain:"“又……又……”两个“又”要一起用，第二个不能换成“也、很、和”。",explainEn:"又…又… is a fixed pair; the second 又 cannot be replaced by 也, 很 or 和."},{kind:"choice",q:"这个手机又贵又___，我不买了。",instr:"完成",instrEn:"Complete the sentence",body:"这个手机又贵又___，我不买了。",options:["难看","好看","方便","漂亮"],answer:0,explain:"“又……又……”连接的两个特点一般都是好的或者都是不好的；“贵”是不好的地方，所以后面是“难看”。说一好一坏要用“虽然……但是……”。",explainEn:"The two qualities in 又…又… usually point the same way; 贵 is a minus, so the other is also a minus (难看). For one good and one bad, use 虽然…但是…."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这双鞋又舒服又便宜。","孩子们又唱又跳，高兴极了。","我又饿又渴，想去吃饭。","这个苹果又大又很甜。"],answer:3,explain:"“又”后面的形容词一般不加“很”，应该说“又大又甜”。",explainEn:"Adjectives after 又 usually take no 很: say 又大又甜."},{q:"翻译：This supermarket is both close and convenient.",a:"这个超市又近又方便。",instr:"翻译",instrEn:"Translate",body:"This supermarket is both close and convenient."}],note:"“又……又……”连接的两个部分通常词性相同。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"yòu + Adjective/Verb + yòu + Adjective/Verb",noteEn:"The two parts joined by 又…又… are usually the same word class.",typeEn:"Coordinate clause"},{id:"NH3.2.2",name:"疑问代词的非疑问用法（2）",pinyin:"yíwèn dàicí de fēi yíwèn yòngfǎ (èr)",type:"代词用法",explainEn:"Use a question word + 都/也 to mean everyone, everything, anywhere, etc.",structure:"疑问代词 + 都/也 + 谓语",examples:[{zh:"谁都可以参加。",en:"Anyone can take part.",py:"Shéi dōu kě yǐ cān jiā."},{zh:"我什么都吃。",en:"I eat everything.",py:"Wǒ shén me dōu chī."},{zh:"你去哪儿都可以。",en:"You can go anywhere.",py:"Nǐ qù nǎr dōu kě yǐ."}],exercises:[{kind:"choice",q:"我太累了，___都不想去。",instr:"辨析",instrEn:"Pick the right one",body:"我太累了，___都不想去。",options:["哪儿","那儿","这儿","什么"],answer:0,explain:"“哪儿+都”表示任何地方；“那儿、这儿”是具体地方，不能跟“都不想去”这样用；去地方不说“什么”。",explainEn:'哪儿都 means "anywhere"; 那儿/这儿 are specific places, and 什么 is not used for places you go.'},{kind:"choice",q:"我今天不舒服，什么都不想吃，___。",instr:"完成",instrEn:"Complete the sentence",body:"我今天不舒服，什么都不想吃，___。",options:["只想吃点儿米饭","只想喝点儿水","想吃个苹果","想吃点儿水果"],answer:1,explain:"“什么都不想吃”表示一点儿东西也不想吃，所以后面不能再说想吃什么，只能说想喝水。",explainEn:"什么都不想吃 means not wanting to eat anything at all, so the speaker can only want to drink water, not eat something."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["坐地铁去哪儿都很方便。","谁都知道这件事。","这儿的人我都谁不认识。","他什么也没说。"],answer:2,explain:"疑问代词要放在“都”前面，应该说“这儿的人我谁都不认识”。",explainEn:"The question word goes before 都: 这儿的人我谁都不认识."},{q:"翻译：Anyone can answer this question.",a:"这个问题谁都能回答。",instr:"翻译",instrEn:"Translate",body:"Anyone can answer this question."}],note:"此时“谁、什么、哪儿”等表示一个范围里的任何一个，不是在提问。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Question word + dōu/yě + Predicate",noteEn:'Here 谁/什么/哪儿 mean "any one" within a range, not a question.',typeEn:"Pronoun usage"},{id:"NH3.2.3",name:"疑问代词的非疑问用法（3）",pinyin:"yíwèn dàicí de fēi yíwèn yòngfǎ (sān)",type:"代词用法",explainEn:"Repeat the same question word in two parts to mean “whatever / whoever / wherever…”.",structure:"疑问代词 + ……，就 + 同一疑问代词 + ……",examples:[{zh:"你想吃什么就点什么。",en:"Order whatever you want to eat.",py:"Nǐ xiǎng chī shén me jiù diǎn shén me."},{zh:"你去哪儿我就去哪儿。",en:"I will go wherever you go.",py:"Nǐ qù nǎr wǒ jiù qù nǎr."},{zh:"谁想参加谁就参加。",en:"Whoever wants to join can join.",py:"Shéi xiǎng cān jiā shéi jiù cān jiā."}],exercises:[{kind:"choice",q:"谁先到，___就先进去。",instr:"辨析",instrEn:"Pick the right one",body:"谁先到，___就先进去。",options:["什么","哪个","哪儿","谁"],answer:3,explain:"前后要用同一个疑问代词，前面是“谁”，后面也用“谁”，意思是“哪个人先到，那个人就先进去”。",explainEn:'Use the same question word in both parts: 谁…谁…, "whoever arrives first goes in first".'},{kind:"choice",q:"这儿的书你想看哪本就看哪本，___。",instr:"完成",instrEn:"Complete the sentence",body:"这儿的书你想看哪本就看哪本，___。",options:["看完放回去就行","但是只能看这一本","我已经给你选好了","不过要先问我看哪本"],answer:0,explain:"“想看哪本就看哪本”表示随便选哪本都可以，所以看完放回去就行；“只能看这一本、已经选好了、要先问我”都不是随便选。",explainEn:'哪本…哪本 means any book you like, so just put it back afterwards; "only this one", "already chosen" or "ask me first" take away the free choice.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你想买哪个就买哪个。","谁先做完，就谁先回家。","哪儿好玩儿，我们就去哪儿。","你怎么想就怎么说吧。"],answer:1,explain:"“就”要放在第二个“谁”后面，应该说“谁先做完，谁就先回家”。",explainEn:"就 goes after the second 谁: 谁先做完，谁就先回家."},{q:"翻译：Take whatever you like.",a:"你喜欢什么就拿什么。",instr:"翻译",instrEn:"Translate",body:"Take whatever you like."}],note:"前后通常使用同一个疑问代词，表示自由选择或对应关系。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Question word + ..., jiù + the same Question word + ...",noteEn:"The same question word appears twice, for free choice or correspondence.",typeEn:"Pronoun usage"}]},{num:3,title:"这个小区挺好的",points:[{id:"NH3.3.1",name:"程度副词“挺”",pinyin:"chéngdù fùcí tǐng",type:"程度副词",explainEn:"Use 挺 + adjective + 的 to mean “quite / pretty”.",structure:"挺 + 形容词 +（的）",examples:[{zh:"这个小区挺安静的。",en:"This neighborhood is quite quiet.",py:"Zhè ge xiǎo qū tǐng ān jìng de."},{zh:"今天挺冷的。",en:"It is pretty cold today.",py:"Jīn tiān tǐng lěng de."},{zh:"这本书挺有意思的。",en:"This book is quite interesting.",py:"Zhè běn shū tǐng yǒu yì si de."}],exercises:[{kind:"choice",q:"这个菜___好吃的，你尝尝。",instr:"辨析",instrEn:"Pick the right one",body:"这个菜___好吃的，你尝尝。",options:["太","真","挺","更"],answer:2,explain:"“挺+形容词+的”是常用说法；“太”要和“了”一起用，“真、更”后面不加“的”。",explainEn:"挺 + adj + 的 is the set pattern; 太 goes with 了, and 真/更 do not take 的 at the end."},{kind:"choice",q:"他的中文挺好的，就是___。",instr:"完成",instrEn:"Complete the sentence",body:"他的中文挺好的，就是___。",options:["一句也不会说","什么都听不懂","跟别人说不了话","说得有点儿慢"],answer:3,explain:"“挺好”表示比较好，所以“就是”后面只能说一个小问题，不能说完全不会。",explainEn:`挺好 means fairly good, so after 就是 only a small problem fits, not "can't speak at all".`},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["今天比昨天挺冷的。","这件衣服挺好看的。","他做饭做得挺好。","我最近挺忙的。"],answer:0,explain:"比较句里不能用“挺”，应该说“今天比昨天冷”或者“今天挺冷的”。",explainEn:"挺 cannot be used in a 比 comparison: say 今天比昨天冷 or 今天挺冷的."},{q:"翻译：The new teacher is pretty friendly.",a:"新老师挺热情的。",instr:"翻译",instrEn:"Translate",body:"The new teacher is pretty friendly."}],note:"口语中很常见，句末经常带“的”。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"tǐng + Adjective + (de)",noteEn:"Very common in speech, often ending with 的.",typeEn:"Degree adverb"},{id:"NH3.3.2",name:"程度补语（1）：形容词/动词 + 坏了",pinyin:"chéngdù bǔyǔ (yī)",type:"程度补语",explainEn:"Use 坏了 after some adjectives or verbs to mean an extremely high degree.",structure:"形容词/动词 + 坏了",examples:[{zh:"我今天累坏了。",en:"I am extremely tired today.",py:"Wǒ jīn tiān lèi huài le."},{zh:"这几天他忙坏了。",en:"He has been extremely busy these days.",py:"Zhè jǐ tiān tā máng huài le."},{zh:"孩子高兴坏了。",en:"The child is extremely happy.",py:"Hái zi gāo xìng huài le."}],exercises:[{kind:"choice",q:"考试得了一百分，她高兴___。",instr:"辨析",instrEn:"Pick the right one",body:"考试得了一百分，她高兴___。",options:["坏","坏了","极","得坏了"],answer:1,explain:"表示程度很高要说“高兴坏了”，“坏”和“极”后面都要有“了”，中间也不加“得”。",explainEn:"The degree form is 高兴坏了: 坏/极 need 了, and no 得 is used."},{kind:"choice",q:"听说儿子考了第一，妈妈高兴坏了，___。",instr:"完成",instrEn:"Complete the sentence",body:"听说儿子考了第一，妈妈高兴坏了，___。",options:["心里很不舒服","身体突然不好了","马上给大家打电话","一点儿也不高兴了"],answer:2,explain:"这里的“坏了”不是“变坏”，表示非常高兴，所以马上告诉大家；其他几个都把“坏了”当成了“不好”。",explainEn:'Here 坏了 does not mean "become bad"; it means extremely happy, so she phones everyone. The others read 坏了 as "bad".'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["跑了一个小时，我渴坏了。","等了半天，他急坏了。","听说你病了，妈妈担心坏了。","爬完山，大家都很累坏了。"],answer:3,explain:"“坏了”已经表示程度很高，前面不能再加“很”，应该说“大家都累坏了”。",explainEn:'坏了 already means "extremely", so drop 很: 大家都累坏了.'},{q:"翻译：I was extremely hungry yesterday.",a:"昨天我饿坏了。",instr:"翻译",instrEn:"Translate",body:"I was extremely hungry yesterday."}],note:"这里的“坏了”不是“变坏”，而是程度补语，表示程度非常高。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Adjective/Verb + huài le (extremely ...)",noteEn:`Here 坏了 isn't "gone bad"; it's a degree complement meaning "extremely".`,typeEn:"Degree complement"},{id:"NH3.3.3",name:"副词“就”和“才”",pinyin:"fùcí jiù hé cái",type:"副词",explainEn:"就 often shows early, fast, or easy. 才 often shows late, slow, or only then.",structure:"时间/条件 + 就/才 + 动词",examples:[{zh:"他六点就起床了。",en:"He got up as early as six.",py:"Tā liù diǎn jiù qǐ chuáng le."},{zh:"我九点才到学校。",en:"I did not arrive at school until nine.",py:"Wǒ jiǔ diǎn cái dào xué xiào."},{zh:"这儿很近，走十分钟就到。",en:"It is close; you can get there in ten minutes.",py:"Zhèr hěn jìn, zǒu shí fēn zhōng jiù dào."}],exercises:[{kind:"choice",q:"电影七点开始，他七点半___到。",instr:"辨析",instrEn:"Pick the right one",body:"电影七点开始，他七点半___到。",options:["才","就","再","又"],answer:0,explain:"电影已经开始了他才到，说明晚了，用“才”；“就”表示早。",explainEn:"He arrived after the film started, which is late, so 才; 就 would mean early."},{kind:"choice",q:"他八点就到了，___。",instr:"完成",instrEn:"Complete the sentence",body:"他八点就到了，___。",options:["比别人都晚","比别人都早","我们等了他很久","他总是迟到"],answer:1,explain:"“就”表示早，所以他比别人早到。",explainEn:"就 shows he was early, so he arrived before the others."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他学了一年就能说中文了。","我等了一个小时，他才来。","我昨天十二点才睡觉了。","这个题很简单，我五分钟就做完了。"],answer:2,explain:"“才”表示晚，后面不加“了”，应该说“十二点才睡觉”。",explainEn:"才 does not take 了 after the verb: 十二点才睡觉."},{q:"翻译：It takes only ten minutes to walk there.",a:"走十分钟就到。",instr:"翻译",instrEn:"Translate",body:"It takes only ten minutes to walk there."}],note:"“就”常让人感觉早、快、容易；“才”常让人感觉晚、慢、少。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Time/Condition + jiù/cái + Verb",noteEn:"就 feels early/fast/easy; 才 feels late/slow/few.",typeEn:"Adverb"}]},{num:4,title:"这家宾馆跟别的都不一样",points:[{id:"NH3.4.1",name:"固定格式“一……也/都 + 不/没……”",pinyin:"yī ... yě/dōu + bù/méi ...",type:"否定结构",explainEn:"Use 一…也/都不/没… to mean “not even one / not at all”.",structure:"一 + 量词 + 名词 + 也/都 + 不/没 + 谓语",examples:[{zh:"我一个苹果也没吃。",en:"I did not eat even one apple.",py:"Wǒ yí ge píng guǒ yě méi chī."},{zh:"他一句话都没说。",en:"He did not say a single word.",py:"Tā yí jù huà dōu méi shuō."},{zh:"今天我一点儿也不累。",en:"I am not tired at all today.",py:"Jīn tiān wǒ yì diǎnr yě bù lèi."}],exercises:[{kind:"choice",q:"我今天太忙了，一口水___没喝。",instr:"辨析",instrEn:"Pick the right one",body:"我今天太忙了，一口水___没喝。",options:["就","才","再","也"],answer:3,explain:"“一……也/都没……”表示一点儿都没有，这里要用“也”。",explainEn:'一…也/都没… means "not even one"; here the word needed is 也.'},{kind:"choice",q:"我昨天太忙了，这本书一页也___。",instr:"完成",instrEn:"Complete the sentence",body:"我昨天太忙了，这本书一页也___。",options:["没看","不看","没看了","不看了"],answer:0,explain:"说过去没做的事要用“没”；“一……也没……”后面不加“了”。",explainEn:"For something that did not happen in the past use 没, and 一…也没… takes no 了."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他一个字也没写。","教室里一个人也有。","我一点儿也不饿。","这些菜我一个都不想吃。"],answer:1,explain:"“一……也”后面要用否定，应该说“一个人也没有”。",explainEn:"一…也 needs a negative: 一个人也没有."},{q:"翻译：I didn't buy a single thing at the store.",a:"我在商店一件东西也没买。",instr:"翻译",instrEn:"Translate",body:"I didn't buy a single thing at the store."}],note:"“没”多否定已经发生的动作；“不”多否定习惯、状态或意愿。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"yī + Measure Word + Noun + yě/dōu + bù/méi + Predicate",noteEn:"没 negates completed actions; 不 negates habits, states or intentions.",typeEn:"Negation"},{id:"NH3.4.2",name:"比较句（9）：“A 跟 B 一样 / 不一样”",pinyin:"bǐjiào jù (jiǔ)",type:"比较句",explainEn:"Use A 跟 B 一样 to say A and B are the same; use 不一样 for different.",structure:"A + 跟 + B + 一样（+ 形容词）/ 不一样",examples:[{zh:"他跟我一样高。",en:"He is as tall as I am.",py:"Tā gēn wǒ yí yàng gāo."},{zh:"这家宾馆跟别的不一样。",en:"This hotel is different from the others.",py:"Zhè jiā bīn guǎn gēn bié de bù yí yàng."},{zh:"我的书跟你的一样。",en:"My book is the same as yours.",py:"Wǒ de shū gēn nǐ de yí yàng."}],exercises:[{kind:"choice",q:"我的手机___你的一样，都是黑色的。",instr:"辨析",instrEn:"Pick the right one",body:"我的手机___你的一样，都是黑色的。",options:["比","给","跟","对"],answer:2,explain:"说两样东西相同用“A跟B一样”；“比”用来说不一样的程度，不能跟“一样”一起用。",explainEn:"To say two things are the same use A跟B一样; 比 compares differences and can't go with 一样."},{kind:"choice",q:"我跟我姐姐一样高，___。",instr:"完成",instrEn:"Complete the sentence",body:"我跟我姐姐一样高，___。",options:["她比我高一点儿","我没有她那么高","我比她矮一点儿","我们都是一米六五"],answer:3,explain:"“A跟B一样高”表示两个人一样高，所以都是一米六五；“比……高、比……矮、没有……高”都表示不一样。",explainEn:"A跟B一样高 means the same height, so both are 1.65 m; 比… and 没有… all mean different heights."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["今天的天气跟昨天冷一样。","我的房间跟你的一样大。","南方的冬天跟北方不一样。","这个字的意思跟那个字一样。"],answer:0,explain:"形容词要放在“一样”后面，应该说“跟昨天一样冷”。",explainEn:"The adjective comes after 一样: 跟昨天一样冷."},{q:"翻译：My hobby is the same as yours.",a:"我的爱好跟你的一样。",instr:"翻译",instrEn:"Translate",body:"My hobby is the same as yours."}],note:"“一样”后面可以再接形容词说明哪方面一样。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"A + gēn + B + yíyàng (+ Adjective) / bù yíyàng",noteEn:"一样 can be followed by an adjective saying in what way they're alike.",typeEn:"Comparison"},{id:"NH3.4.3",name:"固定格式“除了……（以外），……都/还/也……”",pinyin:"chúle ... (yǐwài), ... dōu/hái/yě ...",type:"范围结构",explainEn:"Use 除了…以外 for “except for…” or “besides…”.",structure:"除了 + X +（以外），其他 + 都… / 还/也…",examples:[{zh:"除了我以外，大家都到了。",en:"Everyone arrived except me.",py:"Chú le wǒ yǐ wài, dà jiā dōu dào le."},{zh:"除了汉语以外，我还学英语。",en:"Besides Chinese, I also study English.",py:"Chú le hàn yǔ yǐ wài, wǒ hái xué yīng yǔ."},{zh:"除了苹果，我也喜欢西瓜。",en:"Besides apples, I also like watermelon.",py:"Chú le píng guǒ, wǒ yě xǐ huan xī guā."}],exercises:[{kind:"choice",q:"除了小王，大家___去过上海，只有他没去过。",instr:"辨析",instrEn:"Pick the right one",body:"除了小王，大家___去过上海，只有他没去过。",options:["还","都","也","又"],answer:1,explain:"后面说“只有他没去过”，所以“除了”表示不算小王，后面用“都”；用“还、也”是“除了他，别人也去过”的意思。",explainEn:`Since only he hasn't been, 除了 means "except", which takes 都; 还/也 would mean "besides him, others too".`},{kind:"choice",q:"除了跑步以外，他还___。",instr:"完成",instrEn:"Complete the sentence",body:"除了跑步以外，他还___。",options:["不做别的运动","只喜欢跑步","每天去游泳","什么运动都不做"],answer:2,explain:"“除了……还……”表示除了跑步，又多了一样，所以是“还每天去游泳”；要说只跑步，应该说“除了跑步，他别的运动都不做”。",explainEn:'除了…还… adds something more, so he also swims every day; for "only running" you would say 除了跑步，他别的运动都不做.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["除了米饭，我还想吃饺子。","除了小李以外，大家都同意。","除了唱歌，她也喜欢跳舞。","除了星期天以外，他还每天上班。"],answer:3,explain:"这里是“不算星期天”的意思，要用“都”：除了星期天以外，他每天都上班。",explainEn:'Here 除了 means "except", so use 都: 他每天都上班.'},{q:"翻译：Besides apples, I also bought bananas.",a:"除了苹果以外，我还买了香蕉。",instr:"翻译",instrEn:"Translate",body:"Besides apples, I also bought bananas."}],note:"“都”常表示排除一个例外；“还/也”常表示另外增加一项。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"chúle + X + (yǐwài), Others + dōu... / hái/yě...",noteEn:"都 marks an exception (except…); 还/也 add one more.",typeEn:"Scope structure"}]},{num:5,title:"这样的照片才好看",points:[{id:"NH3.5.1",name:"程度补语（2）：形容词 + 得很",pinyin:"chéngdù bǔyǔ (èr)",type:"程度补语",explainEn:"Use adjective + 得很 to mean “very / extremely”.",structure:"形容词 + 得很",examples:[{zh:"这个小区安静得很。",en:"This neighborhood is very quiet.",py:"Zhè ge xiǎo qū ān jìng de hěn."},{zh:"今天冷得很。",en:"It is very cold today.",py:"Jīn tiān lěng de hěn."},{zh:"这个菜好吃得很。",en:"This dish is very delicious.",py:"Zhè ge cài hǎo chī de hěn."}],exercises:[{kind:"choice",q:"这件大衣贵___，我不想买。",instr:"辨析",instrEn:"Pick the right one",body:"这件大衣贵___，我不想买。",options:["得很","很","地很","极"],answer:0,explain:"表示程度高要说“形容词+得很”；“很”要放在形容词前面，“极”后面要加“了”。",explainEn:"Use adj + 得很 for a high degree; 很 goes before the adjective, and 极 needs 了."},{kind:"choice",q:"这儿的冬天冷得很，___。",instr:"完成",instrEn:"Complete the sentence",body:"这儿的冬天冷得很，___。",options:["可是也不太冷","只比秋天冷一点儿","出门一定要穿大衣","不用穿很多衣服"],answer:2,explain:"“冷得很”表示非常冷，所以出门要穿大衣；“不太冷、只冷一点儿、不用穿很多”都说程度不高，跟“得很”矛盾。",explainEn:'冷得很 means very cold, so you need a coat; "not too cold", "only a bit colder" and "no need for many clothes" all describe a low degree.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这儿的水果新鲜得很。","他最近忙得很。","这个房间很干净得很。","那个公园漂亮得很。"],answer:2,explain:"“得很”已经表示程度高，前面不再加“很”，应该说“这个房间干净得很”。",explainEn:'得很 already means "very", so drop the first 很: 这个房间干净得很.'},{q:"翻译：This room is very comfortable.",a:"这个房间舒服得很。",instr:"翻译",instrEn:"Translate",body:"This room is very comfortable."}],note:"“得很”放在形容词后，口语中表示程度很高。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Adjective + de hěn (very ...)",noteEn:'得很 after an adjective means "very" in speech.',typeEn:"Degree complement"},{id:"NH3.5.2",name:"量词重叠",pinyin:"liàngcí chóngdié",type:"量词重叠",explainEn:"Repeat a measure word to mean “every one / each one”.",structure:"量词重叠 + 都 + 谓语",examples:[{zh:"这些照片张张都很好看。",en:"Every one of these photos looks good.",py:"Zhè xiē zhào piàn zhāng zhāng dōu hěn hǎo kàn."},{zh:"这些苹果个个都很甜。",en:"Every one of these apples is sweet.",py:"Zhè xiē píng guǒ gè gè dōu hěn tián."},{zh:"这些衣服件件都很漂亮。",en:"Every piece of clothing is beautiful.",py:"Zhè xiē yī fu jiàn jiàn dōu hěn piào liang."}],exercises:[{kind:"choice",q:"他写的书___都很有名。",instr:"辨析",instrEn:"Pick the right one",body:"他写的书___都很有名。",options:["个个","张张","件件","本本"],answer:3,explain:"量词重叠要用这个东西自己的量词，书的量词是“本”，所以是“本本”。",explainEn:"Repeat the noun's own measure word; books take 本, so 本本."},{kind:"choice",q:"他家的孩子个个都___。",instr:"完成",instrEn:"Complete the sentence",body:"他家的孩子个个都___。",options:["学习很不错","有的学习好","只有一个学习好","学习好的不多"],answer:0,explain:"“个个都”表示每一个都一样，没有例外，所以不能说“有的、只有一个、不多”。",explainEn:'个个都 means every single one, no exceptions, so "some", "only one" or "not many" do not fit.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这些西瓜个个都很甜。","我们班的同学都个个很努力。","这些桌子张张都很干净。","他的作业次次都写得很好。"],answer:1,explain:"量词重叠要放在“都”前面，应该说“同学个个都很努力”。",explainEn:"The reduplicated measure word goes before 都: 同学个个都很努力."},{q:"翻译：Every one of these cups is very pretty.",a:"这些杯子个个都很漂亮。",instr:"翻译",instrEn:"Translate",body:"Every one of these cups is very pretty."}],note:"量词重叠通常和“都”搭配，表示没有例外。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Reduplicated Measure Word + dōu + Predicate",noteEn:'Reduplicated measure words pair with 都 to mean "without exception".',typeEn:"Measure-word redup."},{id:"NH3.5.3",name:"存现句（3）：地点 + 动词 + 趋向/结果 + 数量 + 人/物",pinyin:"cúnxiàn jù (sān)",type:"存现句",explainEn:"Use place + movement/result verb + an indefinite person/thing to say someone or something appears or moves into a scene.",structure:"地点 + 动词 + 趋向/结果补语 + 数量 + 人/物",examples:[{zh:"前面开过来一辆车。",en:"A car is coming from ahead.",py:"Qián mian kāi guò lái yí liàng chē."},{zh:"门口走进来一个人。",en:"A person walked in through the door.",py:"Mén kǒu zǒu jìn lái yí ge rén."},{zh:"后边跑过来两个孩子。",en:"Two children are running over from behind.",py:"Hòu bian pǎo guò lái liǎng ge hái zi."}],exercises:[{kind:"choice",q:"___走出来一个老人。",instr:"辨析",instrEn:"Pick the right one",body:"___走出来一个老人。",options:["房间","房间里","在房间","在房间里"],answer:1,explain:"这种句子开头直接用表示地方的词，“房间”要加“里”才表示地方，前面不加“在”，所以是“房间里走出来一个老人”。",explainEn:"This sentence type starts with a place word with no 在; 房间 needs 里 to become a place: 房间里走出来一个老人."},{kind:"choice",q:"后面开过来一辆公交车，___。",instr:"完成",instrEn:"Complete the sentence",body:"后面开过来一辆公交车，___。",options:["它已经开远了","它刚从我们这儿开走","它离我们越来越远","我们快站到旁边去吧"],answer:3,explain:"“开过来”表示车朝说话人这边来，所以要站到旁边；“开远、开走、越来越远”都是离开的意思。",explainEn:"开过来 means the bus is coming towards us, so we should step aside; the others all mean moving away."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["桌子上跳下来一只猫。","车上下来很多人。","树上飞下来一只鸟。","那边跑两只小狗过来。"],answer:3,explain:"人或东西要放在“过来”后面，应该说“那边跑过来两只小狗”。",explainEn:"The people or things go after 过来: 那边跑过来两只小狗."},{q:"翻译：Two people walked in from outside.",a:"外面走进来两个人。",instr:"翻译",instrEn:"Translate",body:"Two people walked in from outside."}],note:"句末的人或物通常是不确定、第一次出现的信息。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Place + Verb + Directional/Result Complement + Number + Person/Thing",noteEn:"The person/thing at the end is usually new, indefinite information.",typeEn:"Existential sentence"},{id:"NH3.5.4",name:"紧缩复句“……了……就……”",pinyin:"... le ... jiù ...",type:"承接复句",explainEn:"Use …了…就… when one action finishes and the next action follows soon after.",structure:"动作1 + 了（宾语），就 + 动作2",examples:[{zh:"我吃了饭就去学校。",en:"I will go to school after I eat.",py:"Wǒ chī le fàn jiù qù xué xiào."},{zh:"他下了课就回家。",en:"He goes home as soon as class ends.",py:"Tā xià le kè jiù huí jiā."},{zh:"你到了就给我打电话。",en:"Call me when you arrive.",py:"Nǐ dào le jiù gěi wǒ dǎ diàn huà."}],exercises:[{kind:"choice",q:"他每天下___班就去锻炼身体。",instr:"辨析",instrEn:"Pick the right one",body:"他每天下___班就去锻炼身体。",options:["过","了","着","的"],answer:1,explain:"“动词+了+宾语，就……”表示第一件事做完马上做第二件，所以是“下了班就”。",explainEn:"V + 了 + object + 就 means the second action follows the first: 下了班就…"},{kind:"choice",q:"他下了班就回家了，___。",instr:"完成",instrEn:"Complete the sentence",body:"他下了班就回家了，___。",options:["先跟同事去吃饭了","又工作了一会儿","没跟同事去吃饭","先去超市买东西"],answer:2,explain:"“下了班就回家”表示一下班马上回家，中间没做别的事；“先……、又……”都说他中间做了别的事。",explainEn:"下了班就回家 means he went home right after work with nothing in between; the others add something before going home."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["她洗了手就开始做饭。","你做完了作业就去睡觉吧。","他到了机场就给我打电话了。","我们吃饭了就去看电影。"],answer:3,explain:"“了”要放在动词后面、宾语前面，应该说“吃了饭就去看电影”。",explainEn:"了 goes right after the verb, before the object: 吃了饭就去."},{q:"翻译：He went to bed right after finishing his homework.",a:"他写完了作业就睡觉了。",instr:"翻译",instrEn:"Translate",body:"He went to bed right after finishing his homework."}],note:"两个动作有明显的先后关系，第二个动作紧接着第一个动作。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Action 1 + le (+ Object), jiù + Action 2",noteEn:"The two actions are clearly ordered; the second follows right after.",typeEn:"Sequential clause"}]},{num:6,title:"高铁上还可以点外卖",points:[{id:"NH3.6.1",name:"固定格式“该……了”",pinyin:"gāi ... le",type:"固定格式",explainEn:"Use 该…了 to mean “it is time to…” or “should now…”.",structure:"该 + 动词 + 了",examples:[{zh:"该吃饭了。",en:"It is time to eat.",py:"Gāi chī fàn le."},{zh:"我们该出发了。",en:"It is time for us to leave.",py:"Wǒ men gāi chū fā le."},{zh:"你该休息了。",en:"You should rest now.",py:"Nǐ gāi xiū xi le."}],exercises:[{kind:"choice",q:"都十二点了，我们该回家___。",instr:"辨析",instrEn:"Pick the right one",body:"都十二点了，我们该回家___。",options:["了","过","着","呢"],answer:0,explain:"“该……了”是固定格式，表示到时间了，后面要用“了”。",explainEn:'该…了 is a set pattern meaning "it is time to"; it ends with 了.'},{kind:"choice",q:"___，我们该出发了。",instr:"完成",instrEn:"Complete the sentence",body:"___，我们该出发了。",options:["才六点","快八点了","还早呢","不用着急"],answer:1,explain:"“该……了”表示时间到了，所以前面说“快八点了”；说“还早”就不用出发了。",explainEn:'该…了 means the time has come, so 快八点了 fits; "still early" does not.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我们该去机场了。","我唱完了，现在该你了。","快十二点了，该吃了午饭。","车来了，我们该走了。"],answer:2,explain:"“该……了”的“了”放在句子最后，不放在动词后面，应该说“该吃午饭了”。",explainEn:"In 该…了 the 了 goes at the end of the sentence, not after the verb: 该吃午饭了."},{q:"翻译：It's time for us to go to class.",a:"我们该去上课了。",instr:"翻译",instrEn:"Translate",body:"It's time for us to go to class."}],note:"表示到了做某事的时间，常带提醒语气。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"gāi + Verb + le (it is time to ...)",noteEn:"Marks that it's time to do something, often as a reminder.",typeEn:"Fixed pattern"},{id:"NH3.6.2",name:"假设复句“如果……，就……”",pinyin:"rúguǒ ... jiù ...",type:"条件复句",explainEn:"Use 如果…就… for “if…then…”.",structure:"如果 + 条件，就 + 结果",examples:[{zh:"如果明天下雨，我们就不去了。",en:"If it rains tomorrow, we will not go.",py:"Rú guǒ míng tiān xià yǔ, wǒ men jiù bù qù le."},{zh:"如果你累了，就休息一下。",en:"If you are tired, take a rest.",py:"Rú guǒ nǐ lèi le, jiù xiū xi yí xià."},{zh:"如果有时间，我就去看你。",en:"If I have time, I will go see you.",py:"Rú guǒ yǒu shí jiān, wǒ jiù qù kàn nǐ."}],exercises:[{kind:"choice",q:"___你明天有时间，我们就去爬山吧。",instr:"辨析",instrEn:"Pick the right one",body:"___你明天有时间，我们就去爬山吧。",options:["虽然","所以","不但","如果"],answer:3,explain:"“明天有时间”是一个假设的条件，后面有“就”，所以用“如果”。",explainEn:'"Having time tomorrow" is a condition and goes with 就, so 如果.'},{kind:"choice",q:"如果你不舒服，___。",instr:"完成",instrEn:"Complete the sentence",body:"如果你不舒服，___。",options:["就早点儿回家吧","就早点儿回家了","所以早点儿回家吧","但是早点儿回家吧"],answer:0,explain:"“如果”说的是还没发生的事，后面用“就”，句末用“吧”提建议；不能用“所以、但是”，也不能用表示已经发生的“了”。",explainEn:"如果 is about something not yet real, so use 就 and a suggestion with 吧; not 所以/但是, and not 了 as if it already happened."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["如果你喜欢，就送给你吧。","如果我有钱，就我要去旅游。","如果明天不冷，我们就去公园。","如果你早点儿来，就能见到他了。"],answer:1,explain:"“就”要放在主语后面，应该说“我就要去旅游”。",explainEn:"就 goes after the subject: 我就要去旅游."},{q:"翻译：If you have time tomorrow, come to my house.",a:"如果你明天有时间，就来我家吧。",instr:"翻译",instrEn:"Translate",body:"If you have time tomorrow, come to my house."}],note:"“如果”提出假设条件，“就”引出相应结果。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"rúguǒ + Condition, jiù + Result",noteEn:"如果 sets a hypothetical; 就 gives the result.",typeEn:"Conditional"},{id:"NH3.6.3",name:"固定短语“越来越”",pinyin:"yuèláiyuè",type:"程度结构",explainEn:"Use 越来越 + adjective/mental verb to mean “more and more…”.",structure:"越来越 + 形容词 / 心理动词",examples:[{zh:"天气越来越冷了。",en:"The weather is getting colder and colder.",py:"Tiān qì yuè lái yuè lěng le."},{zh:"他的中文越来越好了。",en:"His Chinese is getting better and better.",py:"Tā de zhōng wén yuè lái yuè hǎo le."},{zh:"我越来越喜欢这个城市了。",en:"I like this city more and more.",py:"Wǒ yuè lái yuè xǐ huan zhè ge chéng shì le."}],exercises:[{kind:"choice",q:"来中国以后，我___喜欢吃饺子了。",instr:"辨析",instrEn:"Pick the right one",body:"来中国以后，我___喜欢吃饺子了。",options:["越","越来","越来越","一点儿"],answer:2,explain:"表示慢慢变化要用“越来越+动词/形容词”；不能只用“越、越来”，“一点儿”也不能放在动词前面。",explainEn:"越来越 + verb/adj shows gradual change; 越 or 越来 alone is wrong, and 一点儿 cannot go before the verb."},{kind:"choice",q:"他的汉语越来越好了，___。",instr:"完成",instrEn:"Complete the sentence",body:"他的汉语越来越好了，___。",options:["跟去年说得一样好","一直都说得很好","可是比以前差了","现在能看中文书了"],answer:3,explain:"“越来越好”表示比以前好，有变化，所以现在能看中文书了；“一样好、一直很好”没有变化，“比以前差”方向反了。",explainEn:'越来越好 means better than before, so now he can read Chinese books; "as good as", "always good" show no change, and "worse" is the opposite.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这个城市越来越很漂亮了。","我越来越喜欢运动了。","来这儿的游客越来越多。","他的个子越来越高了。"],answer:0,explain:"“越来越”后面不加“很”，应该说“越来越漂亮了”。",explainEn:"No 很 after 越来越: 越来越漂亮了."},{q:"翻译：There are more and more cars on the road.",a:"路上的车越来越多了。",instr:"翻译",instrEn:"Translate",body:"There are more and more cars on the road."}],note:"“越来越”后面通常直接接形容词或少数心理动词。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"yuèláiyuè + Adjective / Mental-state Verb",noteEn:"越来越 is usually followed directly by an adjective or a few mental verbs.",typeEn:"Degree structure"}]},{num:7,title:"那条裙子比短裤更好看",points:[{id:"NH3.7.1",name:"连动句（2）：动词1 + 着 + 动词2",pinyin:"liándòng jù (èr)",type:"连动句",explainEn:"Use V1着 + V2 when the first action/state is the manner or background of the second action.",structure:"主语 + 动词1 + 着 +（宾语）+ 动词2",examples:[{zh:"她笑着跟我说话。",en:"She talks to me with a smile.",py:"Tā xiào zhe gēn wǒ shuō huà."},{zh:"他拿着书走进来。",en:"He walked in holding a book.",py:"Tā ná zhe shū zǒu jìn lái."},{zh:"我们坐着聊天。",en:"We chat while sitting.",py:"Wǒ men zuò zhe liáo tiān."}],exercises:[{kind:"choice",q:"我妈妈喜欢听___音乐做饭。",instr:"辨析",instrEn:"Pick the right one",body:"我妈妈喜欢听___音乐做饭。",options:["了","着","过","的"],answer:1,explain:"第一个动作是做第二个动作时的方式，要用“动词1+着+动词2”，所以是“听着音乐做饭”。",explainEn:"The first action is how the second is done, so use V1着 + V2: 听着音乐做饭."},{kind:"choice",q:"王老师总是站着上课，___。",instr:"完成",instrEn:"Complete the sentence",body:"王老师总是站着上课，___。",options:["上完课才站起来","上课的时候坐着","上课时很少坐下来","先站一会儿再上课"],answer:2,explain:"“站着上课”表示上课的时候一直站着，所以上课时很少坐下来；“站着”不是先做的另一个动作，也不能和“坐着上课”同时成立。",explainEn:"站着上课 means he stands the whole time while teaching, so he rarely sits down in class; 站着 is not a separate earlier action."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我喜欢站着喝咖啡。","她笑着跟大家说再见。","他拿着地图找路。","他们看电视着吃饭。"],answer:3,explain:"“着”要紧跟在第一个动词后面，宾语放在“着”后面，应该说“看着电视吃饭”。",explainEn:"着 goes right after the first verb, before its object: 看着电视吃饭."},{q:"翻译：Let's walk to the park.",a:"我们走着去公园吧。",instr:"翻译",instrEn:"Translate",body:"Let's walk to the park."}],note:"V1表示伴随状态或方式，V2是主要动作。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Subject + Verb 1 + zhe + (Object) + Verb 2",noteEn:"V1 is the accompanying manner; V2 is the main action.",typeEn:"Serial-verb sentence"},{id:"NH3.7.2",name:"比较句（10）：“A 不比 B + 形容词”",pinyin:"bǐjiào jù (shí)",type:"比较句",explainEn:"Use A 不比 B + adjective to say A is not more … than B. It does not always mean A is less.",structure:"A + 不比 + B + 形容词",examples:[{zh:"今天不比昨天冷。",en:"Today is not colder than yesterday.",py:"Jīn tiān bù bǐ zuó tiān lěng."},{zh:"我不比姐姐高。",en:"I am not taller than my older sister.",py:"Wǒ bù bǐ jiě jie gāo."},{zh:"这个不比那个贵。",en:"This one is not more expensive than that one.",py:"Zhè ge bù bǐ nà ge guì."}],exercises:[{kind:"choice",q:"她___我高，我们一样高。",instr:"辨析",instrEn:"Pick the right one",body:"她___我高，我们一样高。",options:["不比","没有","比","不跟"],answer:0,explain:"“不比”只说她不更高，可以是一样高；“没有我高”表示她更矮，跟“一样高”矛盾。",explainEn:'不比 only means "not taller", so they can be equal; 没有我高 means shorter, which contradicts 一样高.'},{kind:"choice",q:"我的房间不比你的大，___。",instr:"完成",instrEn:"Complete the sentence",body:"我的房间不比你的大，___。",options:["你的更小","差不多一样大","我的大多了","我的比你的大"],answer:1,explain:"“A不比B大”表示A没有更大，所以可以说两个差不多大。",explainEn:"A不比B大 means A is not bigger, so they can be about the same size."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["坐地铁不比打车慢。","他的汉语不比我差。","今天不比昨天很冷。","这家店的东西不比超市贵。"],answer:2,explain:"比较句里形容词前面不加“很”，应该说“今天不比昨天冷”。",explainEn:"No 很 before the adjective in a comparison: 今天不比昨天冷."},{q:"翻译：The food in this restaurant is no worse than that one's.",a:"这家饭馆的菜不比那家差。",instr:"翻译",instrEn:"Translate",body:"The food in this restaurant is no worse than that one's."}],note:"“A不比B高”只说明A没有比B更高，A可能一样高，也可能更矮。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"A + bù bǐ + B + Adjective",noteEn:"A 不比 B 高 only means A isn't taller; A may be equal or shorter.",typeEn:"Comparison"},{id:"NH3.7.3",name:"程度补语（3）：形容词/动词 + 极了",pinyin:"chéngdù bǔyǔ (sān)",type:"程度补语",explainEn:"Use 极了 after an adjective or feeling verb to mean “extremely”.",structure:"形容词/心理动词 + 极了",examples:[{zh:"这条裙子漂亮极了。",en:"This skirt is extremely beautiful.",py:"Zhè tiáo qún zi piào liang jí le."},{zh:"今天冷极了。",en:"It is extremely cold today.",py:"Jīn tiān lěng jí le."},{zh:"我喜欢极了。",en:"I like it very much.",py:"Wǒ xǐ huan jí le."}],exercises:[{kind:"choice",q:"这个西瓜甜___，你快尝尝。",instr:"辨析",instrEn:"Pick the right one",body:"这个西瓜甜___，你快尝尝。",options:["很","极","得极","极了"],answer:3,explain:"表示程度极高要说“形容词+极了”，“极”后面一定要有“了”，前面不加“得”。",explainEn:"Use adj + 极了; 极 needs 了 and takes no 得."},{kind:"choice",q:"那个公园漂亮极了，___。",instr:"完成",instrEn:"Complete the sentence",body:"那个公园漂亮极了，___。",options:["大家都拍了很多照片","跟别的公园差不多","只是有一点儿好看","没有什么特别的"],answer:0,explain:"“漂亮极了”表示非常漂亮，所以大家拍了很多照片；“差不多、有一点儿好看、没什么特别”程度都太低了。",explainEn:"漂亮极了 means extremely beautiful, so everyone took lots of photos; the others describe only a low degree."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这个地方安静极了。","他非常高兴极了。","我累极了，想睡觉。","她的歌唱得好极了。"],answer:1,explain:"“极了”已经表示程度最高，前面不能再加“非常”，应该说“他高兴极了”。",explainEn:'极了 already means "extremely", so drop 非常: 他高兴极了.'},{q:"翻译：This sofa is extremely comfortable.",a:"这个沙发舒服极了。",instr:"翻译",instrEn:"Translate",body:"This sofa is extremely comfortable."}],note:"“极了”放在形容词或少数心理动词后，程度比“很”强。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Adjective/Mental-state Verb + jí le (extremely ...)",noteEn:"极了 after an adjective/mental verb is stronger than 很.",typeEn:"Degree complement"},{id:"NH3.7.4",name:"递进复句“不但……，而且……”",pinyin:"bùdàn ... érqiě ...",type:"递进复句",explainEn:"Use 不但…而且… for “not only…, but also…”.",structure:"不但 + A，而且 + B",examples:[{zh:"这条裙子不但好看，而且很便宜。",en:"This skirt is not only pretty but also cheap.",py:"Zhè tiáo qún zi bù dàn hǎo kàn, ér qiě hěn pián yi."},{zh:"他不但会说中文，而且会写汉字。",en:"He can not only speak Chinese but also write Chinese characters.",py:"Tā bù dàn huì shuō zhōng wén, ér qiě huì xiě hàn zì."},{zh:"这个小区不但安静，而且很方便。",en:"This neighborhood is not only quiet but also convenient.",py:"Zhè ge xiǎo qū bù dàn ān jìng, ér qiě hěn fāng biàn."}],exercises:[{kind:"choice",q:"他不但会游泳，___会打网球。",instr:"辨析",instrEn:"Pick the right one",body:"他不但会游泳，___会打网球。",options:["但是","所以","而且","还是"],answer:2,explain:"“不但……而且……”表示后面再加一层；“但是”表示转折，“所以”表示结果，“还是”不能这样用。",explainEn:"不但…而且… adds one more point; 但是 shows contrast, 所以 shows result, and 还是 does not fit here."},{kind:"choice",q:"这家宾馆不但很干净，而且___。",instr:"完成",instrEn:"Complete the sentence",body:"这家宾馆不但很干净，而且___。",options:["房间有点儿小","服务不好","有点儿贵","离机场很近"],answer:3,explain:"“不但……而且……”前后说的是同一方向的情况，前面说好的地方，后面也要说好的地方；说不好的地方要用“虽然……但是……”。",explainEn:"不但…而且… keeps the same direction: a good point is followed by another good point; for a drawback use 虽然…但是…."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["不但我喜欢跑步，而且喜欢游泳。","她不但聪明，而且很努力。","这里不但安静，而且很干净。","他不但是老师，而且是画家。"],answer:0,explain:"前后主语相同时，“不但”要放在主语后面，应该说“我不但喜欢跑步，而且喜欢游泳”。",explainEn:"With one subject, 不但 goes after it: 我不但喜欢跑步，而且喜欢游泳."},{q:"翻译：This apartment is not only big but also cheap.",a:"这个房子不但大，而且很便宜。",instr:"翻译",instrEn:"Translate",body:"This apartment is not only big but also cheap."}],note:"后一个分句通常比前一个分句增加一层信息。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"bùdàn + A, érqiě + B (not only..., but also...)",noteEn:"The second clause adds a further layer to the first.",typeEn:"Progressive clause"}]},{num:8,title:"今天我出院了",points:[{id:"NH3.8.1",name:"趋向补语的引申用法（1）：表示结果意义",pinyin:"qūxiàng bǔyǔ de yǐnshēn yòngfǎ (yī)",type:"趋向补语",explainEn:"Some direction words can show a result, not real physical direction, such as 出、起、下.",structure:"动词 + 出/起/下",examples:[{zh:"我终于想出一个好办法。",en:"I finally came up with a good idea.",py:"Wǒ zhōng yú xiǎng chū yí ge hǎo bàn fǎ."},{zh:"我突然想起他的名字了。",en:"I suddenly remembered his name.",py:"Wǒ tū rán xiǎng qǐ tā de míng zi le."},{zh:"请记下我的电话号码。",en:"Please write down my phone number.",py:"Qǐng jì xià wǒ de diàn huà hào mǎ."}],exercises:[{kind:"choice",q:"你听___他是哪儿的人了吗？",instr:"辨析",instrEn:"Pick the right one",body:"你听___他是哪儿的人了吗？",options:["起","出","下","上"],answer:1,explain:"“听出”表示通过听知道了以前不知道的事；“听起”“听下”“听上”都没有这个意思。",explainEn:"听出 means to tell something by listening; 听起/听下/听上 don't have this meaning."},{kind:"choice",q:"我想了半天，还是想不起___。",instr:"完成",instrEn:"Complete the sentence",body:"我想了半天，还是想不起___。",options:["一个好主意","怎么办才好","他叫什么名字","解决的办法"],answer:2,explain:"“想起”是把忘了的事记起来，所以是名字；想新的办法要用“想出”。",explainEn:"想起 is recalling something forgotten, like a name; coming up with a new idea is 想出."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["请写下你的名字。","看到这张照片，我想起了小时候。","你看出他不高兴了吗？","大家一起想下了一个办法。"],answer:3,explain:"想到新的办法要用“想出”，应该说“大家一起想出了一个办法”。",explainEn:"For coming up with a new idea use 想出: 大家一起想出了一个办法."},{q:"翻译：I suddenly remembered that tomorrow is Mom's birthday.",a:"我突然想起明天是妈妈的生日。",instr:"翻译",instrEn:"Translate",body:"I suddenly remembered that tomorrow is Mom's birthday."}],note:"这里“出、起、下”主要表示动作产生了某种结果，不一定是真正的空间方向。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Verb + chū/qǐ/xià (extended result meaning)",noteEn:"Here 出/起/下 mark a result, not necessarily real spatial direction.",typeEn:"Directional compl."},{id:"NH3.8.2",name:"离合词（2）",pinyin:"líhécí (èr)",type:"离合词",explainEn:"A separable verb can have 了, a duration, or a quantity inserted between its two parts.",structure:"A + 了/时量/数量 + B",examples:[{zh:"我住了一个星期院。",en:"I stayed in the hospital for one week.",py:"Wǒ zhù le yí ge xīng qī yuàn."},{zh:"我们上了两个小时课。",en:"We had class for two hours.",py:"Wǒ men shàng le liǎng ge xiǎo shí kè."},{zh:"我昨晚睡了一个好觉。",en:"I had a good sleep last night.",py:"Wǒ zuó wǎn shuì le yí ge hǎo jiào."}],exercises:[{kind:"choice",q:"你上次___，我请你吃饭吧。",instr:"辨析",instrEn:"Pick the right one",body:"你上次___，我请你吃饭吧。",options:["帮了我的忙","帮忙了我","帮忙我了","帮了忙我"],answer:0,explain:"“帮忙”是离合词，后面不能直接带“我”，要把“我的”放在中间：帮了我的忙。",explainEn:"帮忙 is a separable verb and cannot take 我 as an object; put 我的 inside: 帮了我的忙."},{kind:"choice",q:"我跟他只见过___面，还不太了解他。",instr:"完成",instrEn:"Complete the sentence",body:"我跟他只见过___面，还不太了解他。",options:["两天","两次","两个","一下"],answer:1,explain:"离合词中间可以放次数，“见过两次面”表示见面的次数；“两天、两个、一下”不能这样放。",explainEn:"A number of times can go inside a separable verb: 见过两次面; 两天/两个/一下 cannot."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我中午睡了一会儿觉。","我们上个星期考了两次试。","我昨天见面了我的老师。","我们今天上了三节课。"],answer:2,explain:"“见面”是离合词，后面不能直接带人，应该说“我昨天跟我的老师见面了”。",explainEn:"见面 cannot take a person as object: 我昨天跟我的老师见面了."},{q:"翻译：He asked for three days off.",a:"他请了三天假。",instr:"翻译",instrEn:"Translate",body:"He asked for three days off."}],note:"离合词中间可以插入动态助词、时量或数量成分，不能总把它当作普通双音节动词。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"A + le / Duration / Quantity + B (separable verb)",noteEn:"Separable verbs can take particles/duration/quantity inside; not ordinary two-syllable verbs.",typeEn:"Separable verb"},{id:"NH3.8.3",name:"时量补语（2）：表示动作结束后到现在的时间",pinyin:"shíliàng bǔyǔ (èr)",type:"时量补语",explainEn:"Use a duration after a completed/change verb + 了 to say how long it has been since that event.",structure:"主语 + 动词/变化 + 时段 + 了",examples:[{zh:"我来中国两年了。",en:"It has been two years since I came to China.",py:"Wǒ lái zhōng guó liǎng nián le."},{zh:"他毕业三年了。",en:"It has been three years since he graduated.",py:"Tā bì yè sān nián le."},{zh:"开学三个星期了。",en:"It has been three weeks since school started.",py:"Kāi xué sān ge xīng qī le."}],exercises:[{kind:"choice",q:"我___，还没习惯这儿的天气。",instr:"辨析",instrEn:"Pick the right one",body:"我___，还没习惯这儿的天气。",options:["一个月来北京了","来北京了一个月","在北京来一个月了","来北京一个月了"],answer:3,explain:"表示从某件事到现在多长时间，时间放在动词短语后面，句子最后加“了”：来北京一个月了。",explainEn:"To say how long since something happened, put the time after the verb phrase and end with 了."},{kind:"choice",q:"他离开家已经十年了，___。",instr:"完成",instrEn:"Complete the sentence",body:"他离开家已经十年了，___。",options:["很想回去看看","明天就要离开家","下个月才走","还没离开"],answer:0,explain:"“离开家十年了”表示十年前就离开了，所以现在想回去；说“还没离开”就矛盾了。",explainEn:`离开家十年了 means he left ten years ago, so he misses home; "hasn't left yet" contradicts it.`},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我搬家两个月了。","他们三年了结婚。","他出国已经五年了。","我们放假一个星期了。"],answer:1,explain:"时间要放在动词后面，应该说“他们结婚三年了”。",explainEn:"The time goes after the verb: 他们结婚三年了."},{q:"翻译：It has been ten days since my mom left.",a:"我妈妈离开十天了。",instr:"翻译",instrEn:"Translate",body:"It has been ten days since my mom left."}],note:"本点强调“从某动作完成/某变化发生，到现在已经过了多久”。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Subject + Verb/Change + Duration + le",noteEn:"Focus: how long it's been since an action finished or a change occurred.",typeEn:"Duration complement"},{id:"NH3.8.4",name:"固定格式“（在）……以前/以后/前/后”",pinyin:"(zài) ... yǐqián/yǐhòu/qián/hòu",type:"时间结构",explainEn:"Use 以前/前 for “before” and 以后/后 for “after”.",structure:"（在）+ 动作/时间 + 以前/以后；名词/动作 + 前/后",examples:[{zh:"睡觉前我会看一会儿书。",en:"I read for a while before sleeping.",py:"Shuì jiào qián wǒ huì kàn yí huìr shū."},{zh:"下课以后我们去吃饭。",en:"We go eat after class.",py:"Xià kè yǐ hòu wǒ men qù chī fàn."},{zh:"来中国以前，我没吃过饺子。",en:"Before coming to China, I had never eaten jiaozi.",py:"Lái zhōng guó yǐ qián, wǒ méi chī guo jiǎo zi."}],exercises:[{kind:"choice",q:"睡觉___别喝咖啡，会睡不着的。",instr:"辨析",instrEn:"Pick the right one",body:"睡觉___别喝咖啡，会睡不着的。",options:["后","中","前","上"],answer:2,explain:"喝了咖啡会睡不着，所以是睡觉以前别喝，用“前”。",explainEn:"Coffee keeps you awake, so don't drink it before sleeping: 睡觉前."},{kind:"choice",q:"来中国以前，___。",instr:"完成",instrEn:"Complete the sentence",body:"来中国以前，___。",options:["我现在住在北京","我在中国学了一年","我已经在这儿工作了","我一句中文也不会说"],answer:3,explain:"“来中国以前”说的是还没来中国的时候，所以是那时候不会说中文；“现在、在中国、在这儿”说的都是来了以后。",explainEn:"来中国以前 is the time before coming to China, so he could not speak Chinese then; the others describe life after arriving."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["前出门，别忘了关灯。","毕业以后，他去了上海。","回国以后，他常常给我打电话。","考试前我复习了三遍。"],answer:0,explain:"“前”要放在动作后面，应该说“出门前，别忘了关灯”。",explainEn:"前 goes after the action: 出门前，别忘了关灯."},{q:"翻译：Please turn off the light before you leave the room.",a:"离开房间以前，请关灯。",instr:"翻译",instrEn:"Translate",body:"Please turn off the light before you leave the room."}],note:"“以前/以后”可以跟较长短语；“前/后”更简洁。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"(zài) + Action/Time + yǐqián/yǐhòu; Noun/Action + qián/hòu",noteEn:"以前/以后 take longer phrases; 前/后 are more concise.",typeEn:"Time structure"}]},{num:9,title:"打不好没关系",points:[{id:"NH3.9.1",name:"目的复句“为了……，……”",pinyin:"wèile ...",type:"目的复句",explainEn:"Use 为了 + goal to mean “in order to / for the purpose of…”.",structure:"为了 + 目的，主语 + 动作",examples:[{zh:"为了学好中文，我每天练习。",en:"To learn Chinese well, I practice every day.",py:"Wèi le xué hǎo zhōng wén, wǒ měi tiān liàn xí."},{zh:"为了身体健康，他每天跑步。",en:"For his health, he runs every day.",py:"Wèi le shēn tǐ jiàn kāng, tā měi tiān pǎo bù."},{zh:"为了不迟到，我们早点儿出发吧。",en:"Let us leave early so we will not be late.",py:"Wèi le bù chí dào, wǒ men zǎo diǎnr chū fā ba."}],exercises:[{kind:"choice",q:"___多认识一些朋友，他常常去打篮球。",instr:"辨析",instrEn:"Pick the right one",body:"___多认识一些朋友，他常常去打篮球。",options:["因为","为了","所以","如果"],answer:1,explain:"“多认识一些朋友”是他想达到的目的，所以用“为了”；“因为”说已有的原因，“如果”要和“就”一起用。",explainEn:'"Getting to know more friends" is his goal, so 为了; 因为 gives an existing cause, and 如果 needs 就.'},{kind:"choice",q:"为了给妈妈买生日礼物，___。",instr:"完成",instrEn:"Complete the sentence",body:"为了给妈妈买生日礼物，___。",options:["妈妈高兴极了","明天是妈妈的生日","他周末去饭馆工作","他今天不太高兴"],answer:2,explain:"“为了”后面是目的，后面要说为了这个目的做的事，所以是周末去工作；“妈妈高兴、明天是生日”都不是他做的事。",explainEn:"为了 gives a goal, and the second part is what he does for it: working at weekends. The others are not actions he takes."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["为了学好汉语，他来到了中国。","为了看比赛，他们很早就到了。","为了不感冒，你多穿点儿衣服。","为了下雨，我们没去公园。"],answer:3,explain:"“下雨”是原因，不是目的，应该说“因为下雨，我们没去公园”。",explainEn:"Rain is a reason, not a goal: 因为下雨，我们没去公园."},{q:"翻译：In order to do well in the exam, she reviews every day.",a:"为了考好，她每天都复习。",instr:"翻译",instrEn:"Translate",body:"In order to do well in the exam, she reviews every day."}],note:"“为了”后面是目的，后面的句子说明为这个目的做什么。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"wèile + Purpose, Subject + Action",noteEn:"为了 states the purpose; the clause tells what's done for it.",typeEn:"Purpose clause"},{id:"NH3.9.2",name:"可能补语",pinyin:"kěnéng bǔyǔ",type:"可能补语",explainEn:"Use V得/不 + result/direction word to say an action can or cannot reach a result.",structure:"动词 + 得/不 + 补语",examples:[{zh:"这个字我看得懂。",en:"I can understand this character.",py:"Zhè ge zì wǒ kàn de dǒng."},{zh:"声音太小，我听不见。",en:"The sound is too low; I cannot hear it.",py:"Shēng yīn tài xiǎo, wǒ tīng bù jiàn."},{zh:"这么多东西我拿不动。",en:"I cannot carry so many things.",py:"Zhè me duō dōng xi wǒ ná bù dòng."}],exercises:[{kind:"choice",q:"黑板上的字太小了，我看不___。",instr:"辨析",instrEn:"Pick the right one",body:"黑板上的字太小了，我看不___。",options:["清楚","好","完","动"],answer:0,explain:"字太小，是看的结果不清楚，所以说“看不清楚”。",explainEn:"The words are too small, so the result fails to be clear: 看不清楚."},{kind:"choice",q:"这本书我看不懂，因为___。",instr:"完成",instrEn:"Complete the sentence",body:"这本书我看不懂，因为___。",options:["我最近没有时间","我不太喜欢看书","里面很多字我不认识","我已经看过两遍了"],answer:2,explain:"“看不懂”是看了也不能明白，原因是字不认识；“没有时间、不喜欢看书”是不看的原因，不是看不懂的原因。",explainEn:"看不懂 means you read it but can't understand, because of unknown characters; no time or not liking books are reasons for not reading."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你看得见黑板上的字吗？","今天的作业我做不完了。","他说得太快了，我不听懂。","这么高的山，你爬得上去吗？"],answer:2,explain:"表示不能达到结果要把“不”放在动词和补语中间，应该说“我听不懂”。",explainEn:"To say you can't reach the result, put 不 between verb and complement: 听不懂."},{q:"翻译：I cannot hear it.",a:"我听不见。",instr:"翻译",instrEn:"Translate",body:"I cannot hear it."}],note:"可能补语强调“能不能达到某个结果”，不是一般的“能 + 动词”。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Verb + de/bù + Complement (can/cannot achieve the result)",noteEn:"A potential complement asks if a result is achievable, unlike 能 + verb.",typeEn:"Potential compl."},{id:"NH3.9.3",name:"固定格式“越A越B”",pinyin:"yuè A yuè B",type:"程度结构",explainEn:"Use 越 A 越 B to mean “the more A, the more B”.",structure:"越 + A + 越 + B",examples:[{zh:"天气越冷，我越想喝热茶。",en:"The colder it gets, the more I want hot tea.",py:"Tiān qì yuè lěng, wǒ yuè xiǎng hē rè chá."},{zh:"他越说越快。",en:"The more he talks, the faster he speaks.",py:"Tā yuè shuō yuè kuài."},{zh:"中文越学越有意思。",en:"The more I study Chinese, the more interesting it becomes.",py:"Zhōng wén yuè xué yuè yǒu yì si."}],exercises:[{kind:"choice",q:"雨___下越大，我们回家吧。",instr:"辨析",instrEn:"Pick the right one",body:"雨___下越大，我们回家吧。",options:["越来越","更","还","越"],answer:3,explain:"“越A越B”两个“越”要一起用，所以是“越下越大”。",explainEn:"越A越B uses 越 twice: 越下越大."},{kind:"choice",q:"这个歌我越听越喜欢，___。",instr:"完成",instrEn:"Complete the sentence",body:"这个歌我越听越喜欢，___。",options:["每天都要听几遍","听一次就不想听了","现在一点儿也不喜欢","第一次听时最喜欢"],answer:0,explain:"“越听越喜欢”表示听得越多越喜欢，所以每天都要听；其他三个说的都是越来越不喜欢。",explainEn:"越听越喜欢 means the more I listen the more I like it, so I play it every day; the others mean liking it less."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["天越晚，路上的人越少。","他越跑越很快。","我越看越喜欢这件衣服。","人越多，我越紧张。"],answer:1,explain:"第二个“越”后面不加“很”，应该说“他越跑越快”。",explainEn:"No 很 after the second 越: 他越跑越快."},{q:"翻译：The more he talked, the happier he got.",a:"他越说越高兴。",instr:"翻译",instrEn:"Translate",body:"The more he talked, the happier he got."}],note:"两个“越”后面都可以接动作或状态。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"yuè + A + yuè + B (the more A, the more B)",noteEn:"After each 越 you can put an action or a state.",typeEn:"Degree structure"}]},{num:10,title:"你明天再把书还给我",points:[{id:"NH3.10.1",name:"“把”字句（1）：把 + 宾语 + 动词 + 在/到 + 地点",pinyin:"bǎ zì jù (yī)",type:"把字句",explainEn:"Use 把 when an action moves or puts a specific object in a place.",structure:"主语 + 把 + 宾语 + 动词 + 在/到 + 地点",examples:[{zh:"请把书放在桌子上。",en:"Please put the book on the table.",py:"Qǐng bǎ shū fàng zài zhuō zi shàng."},{zh:"我把水果放到冰箱里了。",en:"I put the fruit in the refrigerator.",py:"Wǒ bǎ shuǐ guǒ fàng dào bīng xiāng lǐ le."},{zh:"他把手机放在书包里。",en:"He put the phone in the schoolbag.",py:"Tā bǎ shǒu jī fàng zài shū bāo lǐ."}],exercises:[{kind:"choice",q:"请你把这些书放___书包里。",instr:"辨析",instrEn:"Pick the right one",body:"请你把这些书放___书包里。",options:["着","了","在","给"],answer:2,explain:"“把+东西+动词+在+地方”表示把东西放到那个地方，所以是“放在书包里”。",explainEn:"把 + thing + verb + 在 + place puts it there: 放在书包里."},{kind:"choice",q:"我把你的书放在桌子上了，___。",instr:"完成",instrEn:"Complete the sentence",body:"我把你的书放在桌子上了，___。",options:["书现在还在我手里","它在我的书包里","我还没找到它","你回来自己拿吧"],answer:3,explain:"“把书放在桌子上了”表示书现在在桌子上，所以你自己去拿；说书在我手里、在书包里、没找到，都跟这个意思不一样。",explainEn:"把书放在桌子上了 means the book is now on the table, so you can take it yourself; the other options put it somewhere else."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我把自行车放了门口。","他把照片放在了桌子上。","请把椅子搬到外面去。","我把药放在你的包里了。"],answer:0,explain:"动词后面要有“在”才能带地点，应该说“我把自行车放在门口了”。",explainEn:"A place after the verb needs 在: 我把自行车放在门口了."},{q:"翻译：Please move the chairs into the classroom.",a:"请把椅子搬到教室里。",instr:"翻译",instrEn:"Translate",body:"Please move the chairs into the classroom."}],note:"“把”后的宾语通常是明确、已知的事物；本点重点是动作后的地点。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Subject + bǎ + Object + Verb + zài/dào + Place",noteEn:"The 把 object is definite; focus here is the place after the verb.",typeEn:"把 sentence"},{id:"NH3.10.2",name:"固定格式“在……上/中/下”",pinyin:"zài ... shàng/zhōng/xià",type:"介词结构",explainEn:"Use 在…上 for an aspect, 在…中 for a situation/process, and 在…下 for a condition.",structure:"在 + 名词 + 上/中/下",examples:[{zh:"他在学习上很认真。",en:"He is very serious in his studies.",py:"Tā zài xué xí shàng hěn rèn zhēn."},{zh:"我们在生活中互相帮助。",en:"We help each other in daily life.",py:"Wǒ men zài shēng huó zhōng hù xiāng bāng zhù."},{zh:"在老师的帮助下，我进步很快。",en:"With the teacher’s help, I improved quickly.",py:"Zài lǎo shī de bāng zhù xià, wǒ jìn bù hěn kuài."}],exercises:[{kind:"choice",q:"在妈妈的要求___，他每天都练习写汉字。",instr:"辨析",instrEn:"Pick the right one",body:"在妈妈的要求___，他每天都练习写汉字。",options:["上","下","中","里"],answer:1,explain:"“在……下”表示在某个条件下，“在妈妈的要求下”是常用说法；“上”表示方面，“中、里”表示过程或环境。",explainEn:'在…下 marks a condition: 在妈妈的要求下. 上 means "in terms of", 中/里 mean a process or setting.'},{kind:"choice",q:"在大家的帮助下，___。",instr:"完成",instrEn:"Complete the sentence",body:"在大家的帮助下，___。",options:["大家都很忙","他一个人做完了","他很快学会了游泳","他帮助了大家"],answer:2,explain:"“在大家的帮助下”表示有了大家的帮助，他做成了事，所以是他学会了游泳；“一个人做完、帮助了大家”意思不对。",explainEn:`在大家的帮助下 means with everyone's help he managed something; "did it alone" or "helped everyone" do not fit.`},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["在学习上，他有很多问题。","在生活中，他总是很关心别人。","在工作上，经理对我要求很高。","在同学们的帮助上，我找到了工作。"],answer:3,explain:"“帮助”是条件，要用“在……下”，应该说“在同学们的帮助下”。",explainEn:"Help is a condition, so use 在…下: 在同学们的帮助下."},{q:"翻译：With his parents' help, he bought a house.",a:"在爸爸妈妈的帮助下，他买了房子。",instr:"翻译",instrEn:"Translate",body:"With his parents' help, he bought a house."}],note:"这里的“上/中/下”不是简单方位词，而表示方面、环境或条件。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"zài + Noun + shàng/zhōng/xià",noteEn:"Here 上/中/下 mark an aspect/environment/condition, not location.",typeEn:"Prep. phrase"},{id:"NH3.10.3",name:"“把”字句（2）：把 + 宾语 + 动词 + 给 + 人",pinyin:"bǎ zì jù (èr)",type:"把字句",explainEn:"Use 把 + object + verb + 给 + person when an object is transferred to someone.",structure:"主语 + 把 + 宾语 + 动词 + 给 + 人",examples:[{zh:"你明天再把书还给我。",en:"Return the book to me tomorrow.",py:"Nǐ míng tiān zài bǎ shū huán gěi wǒ."},{zh:"我把照片发给朋友了。",en:"I sent the photo to my friend.",py:"Wǒ bǎ zhào piàn fā gěi péng you le."},{zh:"她把礼物送给老师了。",en:"She gave the gift to the teacher.",py:"Tā bǎ lǐ wù sòng gěi lǎo shī le."}],exercises:[{kind:"choice",q:"我把那本词典借___我的同学了。",instr:"辨析",instrEn:"Pick the right one",body:"我把那本词典借___我的同学了。",options:["给","在","到","对"],answer:0,explain:"把东西交到某人手里，用“动词+给+人”，所以是“借给我的同学”。",explainEn:"When an object passes to a person, use verb + 给 + person: 借给我的同学."},{kind:"choice",q:"我已经把那本书还给___了。",instr:"完成",instrEn:"Complete the sentence",body:"我已经把那本书还给___了。",options:["教室里","老师","桌子上","书包里"],answer:1,explain:"“给”后面是接受东西的人，不是地方，所以是“还给老师”。",explainEn:"After 给 comes the person who receives it, not a place: 还给老师."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["请把这张照片发给我。","他把电脑借给了同事。","我把钱还了给他。","你把这些水果送给经理吧。"],answer:2,explain:"“了”不能放在动词和“给”中间，应该说“我把钱还给他了”。",explainEn:"了 can't go between the verb and 给: 我把钱还给他了."},{q:"翻译：Please return this book to Teacher Wang.",a:"请把这本书还给王老师。",instr:"翻译",instrEn:"Translate",body:"Please return this book to Teacher Wang."}],note:"本点重点是动作的接受者，用“给 + 人”表示。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Subject + bǎ + Object + Verb + gěi + Person",noteEn:"Focus: the recipient, shown with 给 + person.",typeEn:"把 sentence"}]},{num:11,title:"看来我没办法解决这个问题",points:[{id:"NH3.11.1",name:"“还是”和“或者”",pinyin:"háishi hé huòzhě",type:"连词",explainEn:"Use 还是 in a choice question. Use 或者 in a statement.",structure:"问句：A 还是 B？；陈述句：A 或者 B",examples:[{zh:"你喝茶还是咖啡？",en:"Do you want tea or coffee?",py:"Nǐ hē chá hái shì kā fēi?"},{zh:"坐地铁或者坐公交车都可以。",en:"The subway or the bus is fine.",py:"Zuò dì tiě huò zhě zuò gōng jiāo chē dōu kě yǐ."},{zh:"你今天去还是明天去？",en:"Are you going today or tomorrow?",py:"Nǐ jīn tiān qù hái shì míng tiān qù?"}],exercises:[{kind:"choice",q:"你想周六去___周日去呢？",instr:"辨析",instrEn:"Pick the right one",body:"你想周六去___周日去呢？",options:["或者","而且","和","还是"],answer:3,explain:"句子是问对方选哪一个，选择问句要用“还是”；“或者”用在陈述句里。",explainEn:"This asks the listener to choose, so it needs 还是; 或者 is used in statements."},{kind:"choice",q:"A：你喝茶还是喝咖啡？B：___。",instr:"完成",instrEn:"Complete the sentence",body:"A：你喝茶还是喝咖啡？B：___。",options:["对，我要喝","好的，谢谢","咖啡吧，谢谢","是的，我喝"],answer:2,explain:"“还是”问句要从两个里面选一个回答，不能只用“对、好的、是的”来回答。",explainEn:'A 还是 question must be answered by picking one of the choices, not with "yes" or "OK".'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["周末我一般在家看书或者看电视。","你想吃米饭还是面条？","我们明天或者后天去吧。","你们坐地铁去或者打车去呢？"],answer:3,explain:"带“呢”的选择问句要用“还是”，应改为“你们坐地铁去还是打车去呢？”。",explainEn:"A choice question ending in 呢 needs 还是: 你们坐地铁去还是打车去呢？"},{q:"翻译：Tea or milk is fine.",a:"喝茶或者喝牛奶都可以。",instr:"翻译",instrEn:"Translate",body:"Tea or milk is fine."}],note:"最简单记法：选择问句用“还是”，陈述句表示选择通常用“或者”。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Question: A háishi B?; Statement: A huòzhě B",noteEn:"Simple rule: 还是 in choice questions, 或者 in statements.",typeEn:"Conjunction"},{id:"NH3.11.2",name:"固定短语“看来”",pinyin:"kànlái",type:"固定短语",explainEn:"Use 看来 to introduce a conclusion based on what you see or know: “it seems / apparently”.",structure:"看来，+ 判断/结论",examples:[{zh:"看来今天要下雨。",en:"It looks like it is going to rain today.",py:"Kàn lái jīn tiān yào xià yǔ."},{zh:"看来他今天不来了。",en:"It seems he is not coming today.",py:"Kàn lái tā jīn tiān bù lái le."},{zh:"这个问题很难，看来我要请老师帮忙。",en:"This problem is hard; it seems I need the teacher’s help.",py:"Zhè ge wèn tí hěn nán, kàn lái wǒ yào qǐng lǎo shī bāng máng."}],exercises:[{kind:"choice",q:"天这么阴，___马上要下雨了。",instr:"辨析",instrEn:"Pick the right one",body:"天这么阴，___马上要下雨了。",options:["后来","本来","看来","以为"],answer:2,explain:"根据“天这么阴”做出判断，要用“看来”；“以为”表示原来想的不对，而且前面要有主语；“后来、本来”说的是过去。",explainEn:"看来 draws a conclusion from what you see; 以为 means a wrong belief and needs a subject; 后来/本来 refer to the past."},{kind:"choice",q:"___，看来他今天没来上班。",instr:"完成",instrEn:"Complete the sentence",body:"___，看来他今天没来上班。",options:["我刚才在电梯里看见他了","他的包在桌子上放着","他正在楼上开会呢","他的办公室门一直关着"],answer:3,explain:"“看来”前面是做判断的根据，只有“门一直关着”能让人想到他没来；其他几句都说明他来了。",explainEn:"What comes before 看来 is the evidence; only a door that stays closed suggests he did not come — the others show he is here."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["大家都笑了，看来这个故事很有意思。","门开着，看来他已经回来了。","你的脸这么红，看来是发烧了。","我看来，这次考试不太难。"],answer:3,explain:"不能说“我看来”，应改为“看来这次考试不太难”或“在我看来，这次考试不太难”。",explainEn:"You cannot say 我看来; say 看来… or 在我看来…."},{q:"翻译：It seems we need to take a taxi.",a:"看来我们要打车了。",instr:"翻译",instrEn:"Translate",body:"It seems we need to take a taxi."}],note:"“看来”表示根据已有情况作出判断。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"kànlái, + Judgment/Conclusion (it seems ...)",noteEn:"看来 marks a judgement based on the situation.",typeEn:"Set phrase"},{id:"NH3.11.3",name:"“把”字句（3）：把 + 宾语 + 动词 + 结果补语",pinyin:"bǎ zì jù (sān)",type:"把字句",explainEn:"Use 把 + object + verb + result complement to show the result of an action on the object.",structure:"主语 + 把 + 宾语 + 动词 + 结果补语",examples:[{zh:"我把作业写完了。",en:"I finished the homework.",py:"Wǒ bǎ zuò yè xiě wán le."},{zh:"请把门关上。",en:"Please close the door.",py:"Qǐng bǎ mén guān shàng."},{zh:"他把房间打扫干净了。",en:"He cleaned the room.",py:"Tā bǎ fáng jiān dǎ sǎo gān jìng le."}],exercises:[{kind:"choice",q:"我___，明天可以穿了。",instr:"辨析",instrEn:"Pick the right one",body:"我___，明天可以穿了。",options:["把衣服洗了干净","把衣服洗干净了","把衣服干净洗了","把衣服洗得干净了"],answer:1,explain:"结果补语“干净”要紧跟在动词“洗”后面，“了”放在最后；“洗了干净、洗得干净了”都不能这样说。",explainEn:"The result word 干净 goes right after the verb, with 了 at the end; 洗了干净 and 洗得干净了 are wrong."},{kind:"choice",q:"我把这本书看完了，___。",instr:"完成",instrEn:"Complete the sentence",body:"我把这本书看完了，___。",options:["现在借给你吧","可是还没打开它","还有十页没看","明天接着看后面"],answer:0,explain:"“看完”表示已经全部看了，所以可以借给别人；说“还有十页没看”就和“完”矛盾。",explainEn:'看完 means the whole book is read, so it can be lent out; "ten pages left" contradicts 完.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你把这杯水喝完吧。","他把我的名字写错了。","请把桌子打扫。","我把衣服洗干净了。"],answer:2,explain:"“把”字句的动词后面要有结果，应改为“请把桌子打扫干净”。",explainEn:"A 把 sentence needs a result after the verb: 请把桌子打扫干净。"},{q:"翻译：I wrote this character wrong.",a:"我把这个字写错了。",instr:"翻译",instrEn:"Translate",body:"I wrote this character wrong."}],note:"动词后要有结果，不能只说“我把作业写”。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Subject + bǎ + Object + Verb + Result Complement",noteEn:"The verb needs a result; you can't just say 我把作业写.",typeEn:"把 sentence"},{id:"NH3.11.4",name:"固定格式“对……来说”",pinyin:"duì ... láishuō",type:"介词结构",explainEn:"Use 对…来说 to mean “for… / from the point of view of…”.",structure:"对 + 人/事物 + 来说，……",examples:[{zh:"对我来说，健康最重要。",en:"For me, health is the most important.",py:"Duì wǒ lái shuō, jiàn kāng zuì zhòng yào."},{zh:"对学生来说，这个问题有点儿难。",en:"For students, this question is a little difficult.",py:"Duì xué sheng lái shuō, zhè ge wèn tí yǒu diǎnr nán."},{zh:"对他来说，学中文很有意思。",en:"For him, learning Chinese is interesting.",py:"Duì tā lái shuō, xué zhōng wén hěn yǒu yì si."}],exercises:[{kind:"choice",q:"___我来说，数学比历史难。",instr:"辨析",instrEn:"Pick the right one",body:"___我来说，数学比历史难。",options:["给","跟","向","对"],answer:3,explain:"“对……来说”是固定格式，表示从某人的角度看；“跟、给、向”不能和“来说”搭配。",explainEn:`The fixed frame is 对…来说 "for me"; 跟/给/向 don't pair with 来说.`},{kind:"choice",q:"对他来说，___。",instr:"完成",instrEn:"Complete the sentence",body:"对他来说，___。",options:["你们都很喜欢他","我觉得这个题太难了","这个题太简单了","他把这个题做完了"],answer:2,explain:"“对他来说”后面要说从他的角度得出的看法，“我觉得”是别人的看法，“做完了”只是事实。",explainEn:"After 对他来说 comes a judgment from his point of view, not my opinion or a plain fact."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["对我们来看，这个办法不错。","对外国人来说，汉字不太容易。","对我来说，周末最好在家休息。","对孩子来说，这本书有点儿难。"],answer:0,explain:"“对”要和“来说”搭配，应改为“对我们来说”或“在我们看来”。",explainEn:"对 goes with 来说: 对我们来说 (or 在我们看来)."},{q:"翻译：For students, this question is difficult.",a:"对学生来说，这个问题很难。",instr:"翻译",instrEn:"Translate",body:"For students, this question is difficult."}],note:"表示一个评价或判断是从谁的角度出发。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"duì + Person/Thing + láishuō, ... (for/from the perspective of ...)",noteEn:"Marks whose viewpoint an opinion comes from.",typeEn:"Prep. phrase"}]},{num:12,title:"这个季节天气变化很快",points:[{id:"NH3.12.1",name:"选择复句“或者……，或者……”",pinyin:"huòzhě ... huòzhě ...",type:"选择复句",explainEn:"Use 或者…或者… in a statement to list two possible choices.",structure:"或者 + A，或者 + B",examples:[{zh:"周末我们或者去公园，或者在家休息。",en:"On the weekend, we either go to the park or rest at home.",py:"Zhōu mò wǒ men huò zhě qù gōng yuán, huò zhě zài jiā xiū xi."},{zh:"你可以或者坐地铁，或者坐公交车。",en:"You can either take the subway or the bus.",py:"Nǐ kě yǐ huò zhě zuò dì tiě, huò zhě zuò gōng jiāo chē."},{zh:"晚饭或者吃米饭，或者吃面条。",en:"For dinner, we can eat rice or noodles.",py:"Wǎn fàn huò zhě chī mǐ fàn, huò zhě chī miàn tiáo."}],exercises:[{kind:"choice",q:"放假的时候，我们或者去南方，___去北方。",instr:"辨析",instrEn:"Pick the right one",body:"放假的时候，我们或者去南方，___去北方。",options:["或者","还是","又","也"],answer:0,explain:"“或者……，或者……”用在陈述句里列出两个选择，前后都用“或者”；“还是”用在问句里。",explainEn:"In a statement listing two options, both parts take 或者; 还是 is for questions."},{kind:"choice",q:"这个周末，我们或者去公园，或者___，你选一个吧。",instr:"完成",instrEn:"Complete the sentence",body:"这个周末，我们或者去公园，或者___，你选一个吧。",options:["还要看电影","然后看电影","在家看电影","也去看电影"],answer:2,explain:"“或者A，或者B”是两个里面选一个，后面要说另一个选择；“还要、然后、也”是说还要做另一件事。",explainEn:"或者…或者… gives two alternatives; 还要/然后/也 would add another activity instead."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["晚上我或者看书，或者听音乐。","你们或者坐地铁，或者骑自行车，都很方便。","周末你或者在家，或者出去玩儿？","这件事或者你去办，或者我去办。"],answer:2,explain:"问句里表示选择要用“还是”，应改为“周末你在家还是出去玩儿？”。",explainEn:"In a question use 还是: 周末你在家还是出去玩儿？"},{q:"翻译：We can take the subway or the bus.",a:"我们或者坐地铁，或者坐公交车。",instr:"翻译",instrEn:"Translate",body:"We can take the subway or the bus."}],note:"这是陈述句的选择关系，不是问句，因此不用“还是”。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"huòzhě + A, huòzhě + B (either A or B)",noteEn:`This is a statement's "either…or", not a question, so no 还是.`,typeEn:"Alternative clause"},{id:"NH3.12.2",name:"趋向补语的引申用法（2）：表示开始",pinyin:"qūxiàng bǔyǔ de yǐnshēn yòngfǎ (èr)",type:"趋向补语",explainEn:"Use 上 or 起来 after some verbs/adjectives to show a new action or state begins.",structure:"动词/形容词 + 上/起来",examples:[{zh:"天气冷起来了。",en:"The weather has started to get cold.",py:"Tiān qì lěng qǐ lái le."},{zh:"大家笑起来了。",en:"Everyone started laughing.",py:"Dà jiā xiào qǐ lái le."},{zh:"我慢慢喜欢上中文了。",en:"I gradually came to like Chinese.",py:"Wǒ màn màn xǐ huan shàng zhōng wén le."}],exercises:[{kind:"choice",q:"看到妈妈回来，孩子马上高兴___了。",instr:"辨析",instrEn:"Pick the right one",body:"看到妈妈回来，孩子马上高兴___了。",options:["起来","下来","下去","过来"],answer:0,explain:"形容词后加“起来”表示一种情况开始出现，“高兴起来”就是开始高兴；“下去”表示继续。",explainEn:"起来 after an adjective shows a state begins; 下去 means continuing."},{kind:"choice",q:"最近天气热起来了，___。",instr:"完成",instrEn:"Complete the sentence",body:"最近天气热起来了，___。",options:["我们早就开着空调了","我们开始开空调了","可是还是很冷","我们还天天穿大衣"],answer:1,explain:"“热起来”表示最近才开始变热，所以开始开空调；“早就开着空调了”说明早就热了，和“开始”不合。",explainEn:"热起来 means it has only just started to get hot, so we start using the AC; having it on long ago does not fit a beginning."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["天慢慢热起来了。","她慢慢爱上了这个城市。","雨又下起来了。","孩子一看见妈妈就笑下去了。"],answer:3,explain:"表示开始笑要用“起来”，应改为“笑起来了”；“下去”表示继续。",explainEn:"To say the child started laughing use 笑起来; 下去 means continuing."},{q:"翻译：I came to like Chinese.",a:"我喜欢上中文了。",instr:"翻译",instrEn:"Translate",body:"I came to like Chinese."}],note:"这里的“上/起来”表示动作或状态从没有到开始出现。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Verb/Adjective + shàng/qǐlái (begin to ...)",noteEn:"Here 上/起来 mark an action or state beginning to appear.",typeEn:"Directional compl."},{id:"NH3.12.3",name:"范围副词“就”表示范围小/数量少",pinyin:"fànwéi fùcí jiù",type:"范围副词",explainEn:"Use 就 to mean “only / just” when the range or amount is small.",structure:"就 + 数量/人/事物 + 谓语；主语 + 就 + V + 数量",examples:[{zh:"今天就我一个人在家。",en:"Only I am at home today.",py:"Jīn tiān jiù wǒ yí ge rén zài jiā."},{zh:"我就带了两本书。",en:"I brought only two books.",py:"Wǒ jiù dài le liǎng běn shū."},{zh:"他就喝了一杯水。",en:"He drank only one glass of water.",py:"Tā jiù hē le yì bēi shuǐ."}],exercises:[{kind:"choice",q:"我们班___我一个人去过北京，别人都没去过。",instr:"辨析",instrEn:"Pick the right one",body:"我们班___我一个人去过北京，别人都没去过。",options:["都","也","就","还"],answer:2,explain:"“就”放在人前面，表示范围小，“只有我一个人”；“都”“也”“还”不能这样表示“只有”。",explainEn:`就 before a person means "only": only I have been. 都, 也 and 还 can't mean "only" here.`},{kind:"choice",q:"我就买了一个苹果，___。",instr:"完成",instrEn:"Complete the sentence",body:"我就买了一个苹果，___。",options:["苹果太多了，吃不完","冰箱里放不下了","我们两个人吃不饱","我们每人可以吃三个"],answer:2,explain:"“就买了一个”表示数量少，所以两个人“吃不饱”；说“太多了”就意思相反。",explainEn:'就 here means "only one", so there is not enough; "too many" contradicts it.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我喝了就一杯咖啡。","这件衣服我就穿过一次。","家里就我和妈妈两个人。","他就会说几句中文。"],answer:0,explain:"“就”是副词，要放在动词前面，应改为“我就喝了一杯咖啡”。",explainEn:"就 is an adverb and goes before the verb: 我就喝了一杯咖啡。"},{q:"翻译：There is only one student in the classroom.",a:"教室里就有一个学生。",instr:"翻译",instrEn:"Translate",body:"There is only one student in the classroom."}],note:"本点的“就”强调范围或数量很小，意思接近“只”。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"jiù + Quantity/Person/Thing + Predicate; Subject + jiù + Verb + Quantity",noteEn:"Here 就 stresses a small scope/amount, close to 只.",typeEn:"Scope adverb"},{id:"NH3.12.4",name:"趋向补语的引申用法（3）：表示持续",pinyin:"qūxiàng bǔyǔ de yǐnshēn yòngfǎ (sān)",type:"趋向补语",explainEn:"Use 下去/下来 after a verb to show an action or state continues or is kept.",structure:"动词 + 下去/下来",examples:[{zh:"请继续说下去。",en:"Please continue speaking.",py:"Qǐng jì xù shuō xià qù."},{zh:"我们要坚持下去。",en:"We need to keep going.",py:"Wǒ men yào jiān chí xià qù."},{zh:"这个好习惯要保持下来。",en:"This good habit should be kept.",py:"Zhè ge hǎo xí guàn yào bǎo chí xià lái."}],exercises:[{kind:"choice",q:"这个工作虽然很累，可是我想继续做___。",instr:"辨析",instrEn:"Pick the right one",body:"这个工作虽然很累，可是我想继续做___。",options:["下来","起来","过去","下去"],answer:3,explain:"“下去”表示动作继续进行；“下来、起来、过去”没有“继续往后做”的意思。",explainEn:'下去 shows an action goes on; the others do not mean "keep doing".'},{kind:"choice",q:"老师说的话我都记下来了，___。",instr:"完成",instrEn:"Complete the sentence",body:"老师说的话我都记下来了，___。",options:["本子上一句也没有","可是我一个字也没写","你可以看我的本子","所以你去问老师吧"],answer:2,explain:"“记下来”表示把话写下来留着了，所以可以看我的本子；说“一个字也没写”就和“记下来”矛盾。",explainEn:"记下来 means it is written down and kept, so you can read my notebook."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你唱得真好听，请你唱下来。","中文我会一直学下去。","你说得很好，继续说下去。","这个办法很好，我们要一直用下去。"],answer:0,explain:"表示继续唱要用“下去”，应改为“请你唱下去”。",explainEn:'To mean "keep singing" use 下去: 请你唱下去。'},{q:"翻译：I want to keep living in this city.",a:"我想在这个城市继续住下去。",instr:"翻译",instrEn:"Translate",body:"I want to keep living in this city."}],note:"“下去”常强调继续向后发展；“下来”常表示保存、保持到后面。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Verb + xiàqù/xiàlái (continue / keep ...)",noteEn:"下去 stresses continuing on; 下来 stresses keeping/settling.",typeEn:"Directional compl."}]},{num:13,title:"我的新邻居来自英国",points:[{id:"NH3.13.1",name:"假设复句“……的话，就……”",pinyin:"... dehuà, jiù ...",type:"条件复句",explainEn:"Put 的话 after a condition to mean “if…”, often followed by 就.",structure:"条件 + 的话，就 + 结果",examples:[{zh:"明天下雨的话，我们就不去了。",en:"If it rains tomorrow, we will not go.",py:"Míng tiān xià yǔ de huà, wǒ men jiù bù qù le."},{zh:"你累的话，就休息一下。",en:"If you are tired, take a rest.",py:"Nǐ lèi de huà, jiù xiū xi yí xià."},{zh:"有时间的话，就来我家玩儿吧。",en:"If you have time, come to my home.",py:"Yǒu shí jiān de huà, jiù lái wǒ jiā wánr ba."}],exercises:[{kind:"choice",q:"你明天有空___，就来我家吃饭吧。",instr:"辨析",instrEn:"Pick the right one",body:"你明天有空___，就来我家吃饭吧。",options:["因为","如果","只要","的话"],answer:3,explain:"“的话”放在条件后面表示“如果”；“如果、因为、只要”要放在条件的前面。",explainEn:"的话 goes after the condition; 如果/因为/只要 must come before it."},{kind:"choice",q:"饿了的话，___。",instr:"完成",instrEn:"Complete the sentence",body:"饿了的话，___。",options:["就吃了两碗米饭","就已经吃过饭了","就一直没吃东西","就先吃点儿东西吧"],answer:3,explain:"“……的话”说的是假设的条件，后面要说这时候该怎么做，不能说已经发生的事。",explainEn:'……的话 sets up a "what if", so the second part says what to do then, not what already happened.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你不喜欢的话，就别买了。","明天的话下雨，我们就在家。","如果太远的话，我们就打车去。","有问题的话，就问老师。"],answer:1,explain:"“的话”要放在整个条件的后面，应改为“明天下雨的话，我们就在家”。",explainEn:"的话 goes after the whole condition: 明天下雨的话，我们就在家。"},{q:"翻译：If the shop is closed, let's go home.",a:"商店关门的话，我们就回家吧。",instr:"翻译",instrEn:"Translate",body:"If the shop is closed, let's go home."}],note:"“的话”放在条件后面；前面可以省略“如果”。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Condition + dehuà, jiù + Result",noteEn:"的话 follows the condition; 如果 can be dropped in front.",typeEn:"Conditional"},{id:"NH3.13.2",name:"“把”字句（4）：把 + 宾语 + 动词 + 趋向补语",pinyin:"bǎ zì jù (sì)",type:"把字句",explainEn:"Use 把 + object + verb + direction complement to show how the object moves or changes position.",structure:"主语 + 把 + 宾语 + 动词 + 趋向补语",examples:[{zh:"请把书拿出来。",en:"Please take the book out.",py:"Qǐng bǎ shū ná chū lái."},{zh:"你把杯子拿进去吧。",en:"Take the cup inside.",py:"Nǐ bǎ bēi zi ná jìn qù ba."},{zh:"老师把他叫过来了。",en:"The teacher called him over.",py:"Lǎo shī bǎ tā jiào guò lái le."}],exercises:[{kind:"choice",q:"我在楼下等你，你把东西拿___吧。",instr:"辨析",instrEn:"Pick the right one",body:"我在楼下等你，你把东西拿___吧。",options:["下去","上来","下来","上去"],answer:2,explain:"说话人在楼下，东西从楼上向说话人这边移动，要用“下来”；“下去”是离开说话人。",explainEn:"The speaker is downstairs, so the thing moves down toward him: 下来, not 下去."},{kind:"choice",q:"他把椅子搬出去了，___。",instr:"完成",instrEn:"Complete the sentence",body:"他把椅子搬出去了，___。",options:["现在椅子在房间里","房间里多了一把椅子","现在椅子在外面","现在椅子在床旁边"],answer:2,explain:"“搬出去”表示从里面搬到外面，所以椅子现在在外面。",explainEn:"搬出去 means moved out, so the chair is outside now."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你把这些菜拿进去吧。","他把箱子搬进去房间了。","请把椅子搬过来。","他把手机拿出来看了看。"],answer:1,explain:"表示处所的词要放在“进”和“去”中间，应改为“他把箱子搬进房间去了”。",explainEn:"The place word goes between 进 and 去: 搬进房间去了."},{q:"翻译：Please bring the dog back.",a:"请把狗带回来。",instr:"翻译",instrEn:"Translate",body:"Please bring the dog back."}],note:"本点强调“把”字句中的趋向补语，如出来、进去、过来、回去等。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Subject + bǎ + Object + Verb + Directional Complement",noteEn:"Focus: directional complements in the 把 sentence, e.g. 出来/进去/过来/回去.",typeEn:"把 sentence"},{id:"NH3.13.3",name:"并列复句“一边……，一边……”",pinyin:"yìbiān ... yìbiān ...",type:"并列复句",explainEn:"Use 一边…一边… for two actions happening at the same time.",structure:"一边 + 动作1，一边 + 动作2",examples:[{zh:"我一边吃饭，一边看电视。",en:"I eat while watching TV.",py:"Wǒ yì biān chī fàn, yì biān kàn diàn shì."},{zh:"她一边走路，一边听音乐。",en:"She listens to music while walking.",py:"Tā yì biān zǒu lù, yì biān tīng yīn yuè."},{zh:"我们一边喝茶，一边聊天。",en:"We drink tea and chat at the same time.",py:"Wǒ men yì biān hē chá, yì biān liáo tiān."}],exercises:[{kind:"choice",q:"他一边听音乐，___跑步。",instr:"辨析",instrEn:"Pick the right one",body:"他一边听音乐，___跑步。",options:["一边","一下","一会儿","一起"],answer:0,explain:"“一边……一边……”表示两个动作同时进行，前后要用同样的“一边”。",explainEn:"一边…一边… shows two actions at the same time; both parts take 一边."},{kind:"choice",q:"我们一边___，一边聊天儿。",instr:"完成",instrEn:"Complete the sentence",body:"我们一边___，一边聊天儿。",options:["唱歌","睡觉","考试","走路"],answer:3,explain:"“一边……一边……”的两个动作要能同时做，走路的时候可以聊天儿，唱歌、睡觉、考试的时候不能。",explainEn:"The two actions must happen together; you can chat while walking, not while singing, sleeping or taking a test."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["妈妈一边做饭，一边听新闻。","我一边到学校，一边打电话。","他一边看地图，一边找路。","孩子们一边唱歌，一边跳舞。"],answer:1,explain:"“到”一下子就完成，不能持续，不能用在“一边”后面，应改为“我一边往学校走，一边打电话”。",explainEn:"到 happens in an instant, so it can't go with 一边; say 我一边往学校走，一边打电话。"},{q:"翻译：He drinks tea while reading the newspaper.",a:"他一边喝茶，一边看报纸。",instr:"翻译",instrEn:"Translate",body:"He drinks tea while reading the newspaper."}],note:"两个动作通常可以同时进行。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"yìbiān + Action 1, yìbiān + Action 2 (do both at the same time)",noteEn:"The two actions usually happen at the same time.",typeEn:"Coordinate clause"}]},{num:14,title:"这本书被别人借走了",points:[{id:"NH3.14.1",name:"被动句（1）：“被”字句",pinyin:"bèidòng jù (yī)",type:"被动句",explainEn:"Use 被 to say the subject receives an action: “be done by…”.",structure:"A + 被 + B + 动词 + 其他成分",examples:[{zh:"这本书被别人借走了。",en:"This book was borrowed by someone else.",py:"Zhè běn shū bèi bié rén jiè zǒu le."},{zh:"我的苹果被弟弟吃了。",en:"My apple was eaten by my younger brother.",py:"Wǒ de píng guǒ bèi dì di chī le."},{zh:"门被风打开了。",en:"The door was opened by the wind.",py:"Mén bèi fēng dǎ kāi le."}],exercises:[{kind:"choice",q:"我的自行车___人骑走了。",instr:"辨析",instrEn:"Pick the right one",body:"我的自行车___人骑走了。",options:["被","对","向","把"],answer:0,explain:"主语“自行车”是受动作的一方，要用“被”；用“把”的话主语应该是做动作的人。",explainEn:"The bike receives the action, so use 被; with 把 the subject must be the doer."},{kind:"choice",q:"我的伞被同学借走了，___。",instr:"完成",instrEn:"Complete the sentence",body:"我的伞被同学借走了，___。",options:["所以我今天带着它","下雨了我只能跑回家","我打算明天借给他","现在它在我书包里"],answer:1,explain:"“被借走了”表示伞已经不在我这儿了，所以下雨只能跑回家；“明天借给他”说明还没借，不对。",explainEn:"被借走了 means the umbrella is already gone, so I had to run home in the rain."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["那件衣服被妈妈洗干净了。","那本书被他借走了。","他被老师叫到办公室去了。","我的手机被弟弟拿。"],answer:3,explain:"“被”字句的动词后面要有其他成分，应改为“我的手机被弟弟拿走了”。",explainEn:"A 被 sentence needs something after the verb: 我的手机被弟弟拿走了。"},{q:"翻译：The milk was drunk by the cat.",a:"牛奶被猫喝了。",instr:"翻译",instrEn:"Translate",body:"The milk was drunk by the cat."}],note:"HSK3先掌握基本“被”字句；动作后通常要有结果、数量或其他成分。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"A + bèi + B + Verb + Other Elements (A is affected by B)",noteEn:"Learn the basic 被 sentence; the verb needs a result/quantity/etc.",typeEn:"Passive"},{id:"NH3.14.2",name:"承接复句“先……，再/然后……”",pinyin:"xiān ... zài/ránhòu ...",type:"承接复句",explainEn:"Use 先…再/然后… to show the order of actions.",structure:"先 + 动作1，再/然后 + 动作2",examples:[{zh:"我先吃饭，再做作业。",en:"First I eat, then I do homework.",py:"Wǒ xiān chī fàn, zài zuò zuò yè."},{zh:"先洗手，然后吃饭。",en:"Wash your hands first, then eat.",py:"Xiān xǐ shǒu, rán hòu chī fàn."},{zh:"我们先坐地铁，然后走十分钟。",en:"First we take the subway, then walk for ten minutes.",py:"Wǒ men xiān zuò dì tiě, rán hòu zǒu shí fēn zhōng."}],exercises:[{kind:"choice",q:"我们先去超市买东西，___回家做饭。",instr:"辨析",instrEn:"Pick the right one",body:"我们先去超市买东西，___回家做饭。",options:["然后","后来","刚才","已经"],answer:0,explain:"“先……，然后……”说动作的顺序，这里是计划，要用“然后”；“后来”只用来说过去的事。",explainEn:"先…然后… gives the order of steps in a plan; 后来 is only for past events."},{kind:"choice",q:"我先把作业写完，然后___。",instr:"完成",instrEn:"Complete the sentence",body:"我先把作业写完，然后___。",options:["已经玩儿了","再去玩儿","先去玩儿","正在玩儿"],answer:1,explain:"“先……然后再……”表示后做的事，所以是“再去玩儿”；不能再说“先”。",explainEn:"After 然后 comes the later action, 再去玩儿; it can't be 先 again."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我们先看电影，后来去吃饭吧。","你先休息一下，再工作吧。","先买票，然后进去。","我们先坐地铁，然后打车。"],answer:0,explain:"“后来”只用来说过去的事，说计划要用“然后”，应改为“我们先看电影，然后去吃饭吧”。",explainEn:"后来 is only for past events; for a plan use 然后: 我们先看电影，然后去吃饭吧。"},{q:"翻译：First do your homework, then watch TV.",a:"先写作业，然后看电视。",instr:"翻译",instrEn:"Translate",body:"First do your homework, then watch TV."}],note:"“再”常用于下一步动作；“然后”连接前后两个步骤也很常见。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"xiān + Action 1, zài/ránhòu + Action 2",noteEn:"再 is for the next step; 然后 also commonly links two steps.",typeEn:"Sequential clause"},{id:"NH3.14.3",name:"固定格式“X什么（啊）”",pinyin:"X shénme (a)",type:"口语固定格式",explainEn:"Use X什么啊 to reject or question an evaluation: “What do you mean X? / Not X at all!”.",structure:"形容词/动词 + 什么（啊）",examples:[{zh:"累什么啊，我一点儿也不累。",en:"Tired? I am not tired at all.",py:"Lèi shén me a, wǒ yì diǎnr yě bù lèi."},{zh:"贵什么啊，才二十块钱。",en:"Expensive? It is only twenty yuan.",py:"Guì shén me a, cái èr shí kuài qián."},{zh:"难什么啊，这个很简单。",en:"Difficult? This is very easy.",py:"Nán shén me a, zhè ge hěn jiǎn dān."}],exercises:[{kind:"choice",q:"A：你家离学校太远了。B：___什么啊，走路十分钟就到。",instr:"辨析",instrEn:"Pick the right one",body:"A：你家离学校太远了。B：___什么啊，走路十分钟就到。",options:["远","不远","很远","远了"],answer:0,explain:"“X什么啊”直接重复对方说的词表示不同意，前面不加“很”，后面不加“了”；说“不远什么啊”意思就反了。",explainEn:"X什么啊 repeats the bare word to disagree, with no 很 or 了; 不远什么啊 would turn the meaning around."},{kind:"choice",q:"A：你的房间真干净。B：干净什么啊，___。",instr:"完成",instrEn:"Complete the sentence",body:"A：你的房间真干净。B：干净什么啊，___。",options:["我每天都打扫","我昨天刚打扫完","桌子上全是东西","我很喜欢干净"],answer:2,explain:"“干净什么啊”意思是“一点儿也不干净”，后面要说不干净的情况。",explainEn:'干净什么啊 means "it is not clean at all", so what follows must show it is messy.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["饿什么啊，我刚吃过饭。","冷什么啊，今天比昨天热多了。","忙什么啊，我今天一点儿事也没有。","好什么啊，这个菜真好吃。"],answer:3,explain:"“好什么啊”是说“不好”，后面却说“真好吃”，前后矛盾，应改为“好什么啊，这个菜一点儿也不好吃”。",explainEn:`好什么啊 means "not good", so it can't be followed by "really tasty".`},{q:"翻译：Early? It is already nine o'clock.",a:"早什么啊，已经九点了。",instr:"翻译",instrEn:"Translate",body:"Early? It is already nine o'clock."}],note:"很口语，常用于反驳对方刚才的判断，语气要结合场景使用。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Adjective/Verb + shénme (a) (rhetorical denial: 'not ... at all')",noteEn:"Very colloquial; used to rebut what was just said—mind the context.",typeEn:"Colloquial fixed pattern"}]},{num:15,title:"我是半个南京人",points:[{id:"NH3.15.1",name:"介词“根据”",pinyin:"jiècí gēnjù",type:"介词",explainEn:"Use 根据 to mean “according to / based on”.",structure:"根据 + 信息/情况/规定，……",examples:[{zh:"根据天气预报，明天会下雨。",en:"According to the weather forecast, it will rain tomorrow.",py:"Gēn jù tiān qì yù bào, míng tiān huì xià yǔ."},{zh:"根据规定，这里不能停车。",en:"According to the rules, you cannot park here.",py:"Gēn jù guī dìng, zhè lǐ bù néng tíng chē."},{zh:"我们根据地图找到了这个地方。",en:"We found this place using the map.",py:"Wǒ men gēn jù dì tú zhǎo dào le zhè ge dì fang."}],exercises:[{kind:"choice",q:"___老师的要求，我们每天写一百个字。",instr:"辨析",instrEn:"Pick the right one",body:"___老师的要求，我们每天写一百个字。",options:["对","在","根据","向"],answer:2,explain:"“根据”表示按照某个要求去做；“在”要说成“在老师的要求下”，“对、向”不能这样用。",explainEn:`根据 means "according to" a requirement; 在 would need 在…下, and 对/向 don't fit here.`},{kind:"choice",q:"根据这张地图，___。",instr:"完成",instrEn:"Complete the sentence",body:"根据这张地图，___。",options:["前面右边就是银行","我很喜欢这张地图","这张地图是新买的","地图在我的包里"],answer:0,explain:"“根据地图”后面是从地图上得到的信息；喜欢地图、地图是新的都不是从地图上知道的。",explainEn:"After 根据地图 comes what the map tells you, not facts about the map itself."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["根据学校的要求，学生上课不能用手机。","根据大家的要求，我们周六去公园。","我们根据他的介绍找到了饭馆。","根据我，这个办法很好。"],answer:3,explain:"“根据”后面不能只放一个人来表示看法，应改为“在我看来，这个办法很好”。",explainEn:"根据 can't take just a person to give an opinion; say 在我看来."},{q:"翻译：According to the news, it will be very cold tomorrow.",a:"根据新闻，明天会很冷。",instr:"翻译",instrEn:"Translate",body:"According to the news, it will be very cold tomorrow."}],note:"“根据”后面是判断、行动所依据的信息或标准。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"gēnjù + Information/Situation/Rule, ... (according to ...)",noteEn:"根据 is followed by the basis for a judgement or action.",typeEn:"Preposition"},{id:"NH3.15.2",name:"数量重叠“数词 + 量词 + 数词 + 量词”",pinyin:"shùliàng chóngdié: shùcí + liàngcí + shùcí + liàngcí",type:"数量重叠",explainEn:"Repeat a number-measure phrase to mean people/things act in groups or one by one.",structure:"数词 + 量词 + 数词 + 量词 +（地）+ 动词",examples:[{zh:"请一个一个地进来。",en:"Please come in one by one.",py:"Qǐng yí ge yí ge de jìn lái."},{zh:"学生两个两个地练习。",en:"The students practice in pairs.",py:"Xué sheng liǎng ge liǎng ge de liàn xí."},{zh:"照片一张一张地看。",en:"Look at the photos one by one.",py:"Zhào piàn yì zhāng yì zhāng de kàn."}],exercises:[{kind:"choice",q:"他把桌子上的书___地放进包里。",instr:"辨析",instrEn:"Pick the right one",body:"他把桌子上的书___地放进包里。",options:["一张一张","一件一件","一条一条","一本一本"],answer:3,explain:"数量重叠要用和名词搭配的量词，书用“本”，所以是“一本一本地”。",explainEn:"The repeated measure word must match the noun; books take 本."},{kind:"choice",q:"老师让我们一个一个地进去，___。",instr:"完成",instrEn:"Complete the sentence",body:"老师让我们一个一个地进去，___。",options:["所以大家一起进去了","别的人就在外面等着","我们五个人一起进去了","所以大家都不用等了"],answer:1,explain:"“一个一个地进去”表示每次只进去一个人，所以别的人要在外面等；“一起进去”就不对了。",explainEn:"One by one means only one goes in at a time, so the others wait outside."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我们看照片一张一张地。","老师让我们两个两个地练习对话。","请把这些字一个一个地写清楚。","他把衣服一件一件地洗干净了。"],answer:0,explain:"“数量重叠 + 地”要放在动词前面，应改为“我们一张一张地看照片”。",explainEn:"The repeated phrase + 地 goes before the verb: 我们一张一张地看照片。"},{q:"翻译：He ate the dumplings one by one.",a:"他把饺子一个一个地吃完了。",instr:"翻译",instrEn:"Translate",body:"He ate the dumplings one by one."}],note:"表示按固定数量分组或依次进行，常加“地”修饰后面的动作。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Number + Measure Word + Number + Measure Word + (de) + Verb",noteEn:"Means in fixed groups or one by one, often with 地 before the verb.",typeEn:"Quantity reduplication"},{id:"NH3.15.3",name:"固定短语“在……看来”",pinyin:"zài ... kànlái",type:"固定短语",explainEn:"Use 在…看来 to mean “in someone’s view / in the opinion of…”.",structure:"在 + 人/群体 + 看来，……",examples:[{zh:"在我看来，健康最重要。",en:"In my view, health is the most important.",py:"Zài wǒ kàn lái, jiàn kāng zuì zhòng yào."},{zh:"在老师看来，他进步很大。",en:"In the teacher’s view, he has improved a lot.",py:"Zài lǎo shī kàn lái, tā jìn bù hěn dà."},{zh:"在很多人看来，这个办法不错。",en:"In many people’s view, this method is good.",py:"Zài hěn duō rén kàn lái, zhè ge bàn fǎ bù cuò."}],exercises:[{kind:"choice",q:"___很多外国人看来，汉字很难写。",instr:"辨析",instrEn:"Pick the right one",body:"___很多外国人看来，汉字很难写。",options:["给","在","跟","对"],answer:1,explain:"固定格式是“在……看来”；“对”要和“来说”搭配。",explainEn:"The fixed frame is 在…看来; 对 pairs with 来说, not 看来."},{kind:"choice",q:"在妈妈看来，___。",instr:"完成",instrEn:"Complete the sentence",body:"在妈妈看来，___。",options:["我还是一个孩子","她看见我回来了","你应该问问妈妈","我觉得妈妈太累了"],answer:0,explain:"“在妈妈看来”后面是妈妈的看法；“我觉得”是我的看法，“看见我回来了”不是看法。",explainEn:"After 在妈妈看来 comes Mom's opinion, not mine or a plain fact."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["在他看来，这件事没那么简单。","在我看起来，这个问题不难。","在孩子们看来，大熊猫非常可爱。","在老人看来，健康比钱重要。"],answer:1,explain:"固定说法是“在……看来”，不能说“在……看起来”，应改为“在我看来，这个问题不难”。",explainEn:"The fixed form is 在…看来, not 在…看起来: 在我看来，这个问题不难。"},{q:"翻译：In my father's view, learning history is very important.",a:"在爸爸看来，学历史很重要。",instr:"翻译",instrEn:"Translate",body:"In my father's view, learning history is very important."}],note:"和“看来”不同，“在……看来”明确说明是谁的观点。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"zài + Person/Group + kànlái, ... (in ...'s view)",noteEn:"Unlike 看来, 在…看来 makes clear whose view it is.",typeEn:"Set phrase"},{id:"NH3.15.4",name:"固定短语“不一会儿”",pinyin:"bù yíhuìr",type:"时间短语",explainEn:"Use 不一会儿 to mean “after a short while / soon”.",structure:"不一会儿，+ 新情况",examples:[{zh:"不一会儿，车就来了。",en:"After a short while, the car came.",py:"Bù yí huìr, chē jiù lái le."},{zh:"他进去不一会儿就出来了。",en:"He came out soon after going in.",py:"Tā jìn qù bù yí huìr jiù chū lái le."},{zh:"不一会儿，大家都到了。",en:"Soon, everyone arrived.",py:"Bù yí huìr, dà jiā dōu dào le."}],exercises:[{kind:"choice",q:"雨下得很大，可是___，天就晴了。",instr:"辨析",instrEn:"Pick the right one",body:"雨下得很大，可是___，天就晴了。",options:["一直","很久","不一会儿","半天"],answer:2,explain:"“不一会儿”表示时间很短，后面常用“就”；“很久、半天”表示时间长，不能这样用。",explainEn:"不一会儿 means a short time later, often with 就; 很久/半天 mean a long time."},{kind:"choice",q:"我给他打了电话，不一会儿，___。",instr:"完成",instrEn:"Complete the sentence",body:"我给他打了电话，不一会儿，___。",options:["他一直没来","他就到了","他三天后到了","他昨天就来了"],answer:1,explain:"“不一会儿”说的是很短的时间以后出现的新情况，所以是“他就到了”。",explainEn:"不一会儿 introduces something that happens a moment later."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他上床不一会儿就睡着了。","不一会儿，教室里的人都走了。","我们坐下不一会儿，菜就上来了。","不一会儿，他已经学了三年中文。"],answer:3,explain:"“不一会儿”表示很短的时间，不能和“三年”这样长的时间一起用，应改为“他已经学了三年中文”。",explainEn:`不一会儿 means a short moment; it can't go with "three years".`},{q:"翻译：Soon, the children all fell asleep.",a:"不一会儿，孩子们都睡了。",instr:"翻译",instrEn:"Translate",body:"Soon, the children all fell asleep."}],note:"表示经过的时间很短。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"bù yíhuìr, + New Situation (after a short while ...)",noteEn:"Means only a short time passed.",typeEn:"Time phrase"}]},{num:16,title:"我听说有的熊猫出国了",points:[{id:"NH3.16.1",name:"并列复句“一会儿……，一会儿……”",pinyin:"yíhuìr ... yíhuìr ...",type:"并列复句",explainEn:"Use 一会儿…一会儿… when two actions or states alternate.",structure:"一会儿 + A，一会儿 + B",examples:[{zh:"天气一会儿晴，一会儿下雨。",en:"The weather is sunny one moment and rainy the next.",py:"Tiān qì yí huìr qíng, yí huìr xià yǔ."},{zh:"他一会儿看书，一会儿看手机。",en:"He reads for a while, then looks at his phone.",py:"Tā yí huìr kàn shū, yí huìr kàn shǒu jī."},{zh:"孩子一会儿笑，一会儿哭。",en:"The child laughs one moment and cries the next.",py:"Hái zi yí huìr xiào, yí huìr kū."}],exercises:[{kind:"choice",q:"他不知道怎么办，一会儿想去，___又不想去。",instr:"辨析",instrEn:"Pick the right one",body:"他不知道怎么办，一会儿想去，___又不想去。",options:["一边","一会儿","一点儿","一下"],answer:1,explain:"“一会儿A，一会儿B”表示两种情况来回变化，前后都用“一会儿”；“一边”表示同时做。",explainEn:"一会儿…一会儿… shows switching back and forth; 一边 means at the same time."},{kind:"choice",q:"这几天的天气一会儿冷，一会儿___。",instr:"完成",instrEn:"Complete the sentence",body:"这几天的天气一会儿冷，一会儿___。",options:["更冷","也冷","热","一直冷"],answer:2,explain:"“一会儿……一会儿……”说的是两种不同的情况来回变，冷的后面要说“热”。",explainEn:"一会儿…一会儿… needs two different states, so cold alternates with hot."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["她一会儿高兴，一边难过。","孩子一会儿要喝水，一会儿要吃东西。","他一会儿说要去，一会儿说不去。","灯一会儿开，一会儿关。"],answer:0,explain:"前后要用同样的词，应改为“她一会儿高兴，一会儿难过”。",explainEn:"Both halves take the same word: 一会儿高兴，一会儿难过。"},{q:"翻译：He sits down one moment and stands up the next.",a:"他一会儿坐下，一会儿站起来。",instr:"翻译",instrEn:"Translate",body:"He sits down one moment and stands up the next."}],note:"重点是两个动作或状态交替出现，不是同时发生。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"yíhuìr + A, yíhuìr + B (now A, now B)",noteEn:"The point is two actions alternate, not happen at once.",typeEn:"Coordinate clause"},{id:"NH3.16.2",name:"介词“关于”",pinyin:"jiècí guānyú",type:"介词",explainEn:"Use 关于 before a topic to mean “about / concerning”.",structure:"关于 + 话题 +（的）+ 名词/句子",examples:[{zh:"关于这个问题，我想再说两句。",en:"I want to say a little more about this question.",py:"Guān yú zhè ge wèn tí, wǒ xiǎng zài shuō liǎng jù."},{zh:"这是一本关于中国文化的书。",en:"This is a book about Chinese culture.",py:"Zhè shì yì běn guān yú zhōng guó wén huà de shū."},{zh:"关于明天的考试，老师说了很多。",en:"The teacher said a lot about tomorrow’s test.",py:"Guān yú míng tiān de kǎo shì, lǎo shī shuō le hěn duō."}],exercises:[{kind:"choice",q:"我看了一本___大熊猫的书。",instr:"辨析",instrEn:"Pick the right one",body:"我看了一本___大熊猫的书。",options:["根据","对","关于","向"],answer:2,explain:"“关于 + 话题 + 的 + 名词”表示内容是什么，“关于大熊猫的书”就是写大熊猫的书。",explainEn:'关于 + topic + 的 + noun means "a book about…".'},{kind:"choice",q:"关于去哪儿旅游，___。",instr:"完成",instrEn:"Complete the sentence",body:"关于去哪儿旅游，___。",options:["大家说的都不一样","火车票很便宜","我很喜欢这个城市","他们昨天出发了"],answer:0,explain:"“关于”引出话题，后面要说跟这个话题有关的内容，就是“去哪儿”的想法。",explainEn:'关于 introduces the topic "where to travel"; the rest must talk about that.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["关于考试的时间，老师还没告诉我们。","他关于这件事很感兴趣。","他给我们讲了一个关于月亮的故事。","关于这件事，我们明天再说。"],answer:1,explain:"表示对人或事的态度、兴趣要用“对”，应改为“他对这件事很感兴趣”。",explainEn:"For interest or attitude use 对, not 关于: 他对这件事很感兴趣。"},{q:"翻译：a book about Chinese culture",a:"一本关于中国文化的书",instr:"翻译",instrEn:"Translate",body:"a book about Chinese culture"}],note:"“关于 + 话题”常放在句首；修饰名词时常用“关于……的 + 名词”。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"guānyú + Topic + (de) + Noun/Sentence (about ...)",noteEn:"关于 + topic often opens the sentence; to modify a noun use 关于…的 + noun.",typeEn:"Preposition"},{id:"NH3.16.3",name:"固定短语“一般来说”",pinyin:"yìbān láishuō",type:"固定短语",explainEn:"Use 一般来说 to mean “generally speaking / in general”.",structure:"一般来说，+ 一般情况",examples:[{zh:"一般来说，冬天比秋天冷。",en:"Generally speaking, winter is colder than autumn.",py:"Yì bān lái shuō, dōng tiān bǐ qiū tiān lěng."},{zh:"一般来说，年轻人学得比较快。",en:"Generally speaking, young people learn relatively quickly.",py:"Yì bān lái shuō, nián qīng rén xué de bǐ jiào kuài."},{zh:"一般来说，这里的春天很舒服。",en:"Generally speaking, spring here is comfortable.",py:"Yì bān lái shuō, zhè lǐ de chūn tiān hěn shū fu."}],exercises:[{kind:"choice",q:"___，早上六点以前地铁里人很少。",instr:"辨析",instrEn:"Pick the right one",body:"___，早上六点以前地铁里人很少。",options:["对我来说","一般来说","一直","刚才"],answer:1,explain:"“一般来说”放在句首说平常的情况；“对我来说”后面要说自己的看法或感受，“一直”不能单独放在句首，“刚才”说的是某一次。",explainEn:"一般来说 introduces what is usually true; 对我来说 introduces a personal view, 一直 can't stand alone at the start, and 刚才 is one specific time."},{kind:"choice",q:"一般来说，___，可是今年不一样。",instr:"完成",instrEn:"Complete the sentence",body:"一般来说，___，可是今年不一样。",options:["他明天要考试","我昨天去了北京","这里夏天不太热","这里今年夏天很热"],answer:2,explain:"“一般来说”后面是平常的情况，不说某一次具体的事。",explainEn:"一般来说 is followed by a general fact, not a one-time event."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["一般来说，坐高铁比坐飞机便宜。","一般来说，周末公园里人很多。","一般来说，孩子都喜欢吃甜的。","一般来说，我昨天七点起床。"],answer:3,explain:"“一般来说”说的是平常的情况，不能和“昨天”这样的具体时间一起用，应改为“一般来说，我七点起床”。",explainEn:"一般来说 is for usual facts, not one specific day like 昨天."},{q:"翻译：Generally speaking, autumn is quite cool.",a:"一般来说，秋天比较凉快。",instr:"翻译",instrEn:"Translate",body:"Generally speaking, autumn is quite cool."}],note:"用于说明通常情况，不表示每一个人或每一种情况都完全如此。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"yìbān láishuō, + General Situation (generally speaking ...)",noteEn:"States the general case, not that every single instance is so.",typeEn:"Set phrase"},{id:"NH3.16.4",name:"比较句（11）：比 + 多/少/早/晚 + 动词 + 数量",pinyin:"bǐjiào jù (shíyī)",type:"比较句",explainEn:"Use 比 + 多/少/早/晚 + verb + amount to show an exact difference in an action.",structure:"A + 比 + B + 多/少/早/晚 + 动词 + 数量",examples:[{zh:"我今天比昨天早起半个小时。",en:"I got up half an hour earlier today than yesterday.",py:"Wǒ jīn tiān bǐ zuó tiān zǎo qǐ bàn ge xiǎo shí."},{zh:"他比我多学了一年中文。",en:"He has studied Chinese one year longer than I have.",py:"Tā bǐ wǒ duō xué le yì nián zhōng wén."},{zh:"这家店比那家晚关门一个小时。",en:"This shop closes one hour later than that one.",py:"Zhè jiā diàn bǐ nà jiā wǎn guān mén yí ge xiǎo shí."}],exercises:[{kind:"choice",q:"我比他___到了十分钟，一直在等他。",instr:"辨析",instrEn:"Pick the right one",body:"我比他___到了十分钟，一直在等他。",options:["晚","多","少","早"],answer:3,explain:"我在等他，说明我先到，所以是“早到了十分钟”；“晚到”的话就是他等我。",explainEn:"I was waiting for him, so I arrived earlier: 早到; 晚到 would mean he waited."},{kind:"choice",q:"我比哥哥少吃了两个饺子，___。",instr:"完成",instrEn:"Complete the sentence",body:"我比哥哥少吃了两个饺子，___。",options:["所以哥哥吃得更多","所以我吃得更多","所以我们吃得一样多","所以哥哥吃得更少"],answer:0,explain:"“我比哥哥少吃了两个”表示哥哥比我多吃了两个。",explainEn:"I ate two fewer than my brother, so he ate more."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我比你少喝了一杯咖啡。","我比他喝了多两杯水。","妹妹比我少花了一百块钱。","他比我晚到了五分钟。"],answer:1,explain:"“多/少/早/晚”要放在动词前面，应改为“我比他多喝了两杯水”。",explainEn:"多/少/早/晚 goes before the verb: 我比他多喝了两杯水。"},{q:"翻译：She bought two more books than me.",a:"她比我多买了两本书。",instr:"翻译",instrEn:"Translate",body:"She bought two more books than me."}],note:"这里比较的是动作在时间或数量上的具体差别。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"A + bǐ + B + duō/shǎo/zǎo/wǎn + Verb + Quantity",noteEn:"Here it compares a concrete difference in time or amount of an action.",typeEn:"Comparison"}]},{num:17,title:"我要多向认真的人学习",points:[{id:"NH3.17.1",name:"介词“向”",pinyin:"jiècí xiàng",type:"介词",explainEn:"Use 向 + person/direction before a verb to mean “toward / to / from someone”.",structure:"向 + 人/方向 + 动词",examples:[{zh:"我要向老师学习。",en:"I want to learn from the teacher.",py:"Wǒ yào xiàng lǎo shī xué xí."},{zh:"他向大家介绍了自己。",en:"He introduced himself to everyone.",py:"Tā xiàng dà jiā jiè shào le zì jǐ."},{zh:"请向前走。",en:"Please walk forward.",py:"Qǐng xiàng qián zǒu."}],exercises:[{kind:"choice",q:"他___我借了一本词典。",instr:"辨析",instrEn:"Pick the right one",body:"他___我借了一本词典。",options:["向","往","对","在"],answer:0,explain:"“向 + 人 + 借”表示从这个人那儿借；“往”后面多是方向，不放借东西的人。",explainEn:"向 + person + 借 means borrow from someone; 往 is used with directions."},{kind:"choice",q:"我们应该向他学习，因为___。",instr:"完成",instrEn:"Complete the sentence",body:"我们应该向他学习，因为___。",options:["他学习非常努力","他想跟我们学习","他需要我们帮忙","他学习不太好"],answer:0,explain:"“向他学习”表示他做得好，我们要学他，所以原因是他很努力；“他想跟我们学习”方向反了。",explainEn:'向他学习 means he is a good model for us, so the reason is that he works hard; "he wants to learn from us" is the wrong direction.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["孩子向妈妈跑过去。","他向大家问好。","他向我很热情。","我向老师请假了。"],answer:2,explain:"对人的态度要用“对”，应改为“他对我很热情”。",explainEn:"For an attitude toward someone use 对: 他对我很热情。"},{q:"翻译：I want to ask the teacher a question.",a:"我想向老师问一个问题。",instr:"翻译",instrEn:"Translate",body:"I want to ask the teacher a question."}],note:"“向”常引出动作的方向或对象，如“向老师学习、向大家介绍”。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"xiàng + Person/Direction + Verb",noteEn:"向 introduces direction/target, e.g. 向老师学习, 向大家介绍.",typeEn:"Preposition"},{id:"NH3.17.2",name:"反问句“不是……吗？”",pinyin:"bú shì ... ma",type:"反问句",explainEn:"Use 不是…吗？ to remind or challenge someone about something you think is already true.",structure:"不是 + 句子 + 吗？",examples:[{zh:"你不是说今天来吗？",en:"Didn’t you say you were coming today?",py:"Nǐ bù shì shuō jīn tiān lái ma?"},{zh:"他不是老师吗？",en:"Isn’t he a teacher?",py:"Tā bù shì lǎo shī ma?"},{zh:"我们不是已经见过吗？",en:"Haven’t we already met?",py:"Wǒ men bù shì yǐ jīng jiàn guo ma?"}],exercises:[{kind:"choice",q:"你___说今天要去图书馆吗？怎么还在家？",instr:"辨析",instrEn:"Pick the right one",body:"你___说今天要去图书馆吗？怎么还在家？",options:["是不是","别","不","不是"],answer:3,explain:"“不是……吗？”是反问，提醒对方他说过的话；“是不是”后面不能再加“吗”。",explainEn:"不是…吗？ reminds the listener of what they said; 是不是 can't take 吗."},{kind:"choice",q:"你不是会说中文吗？___",instr:"完成",instrEn:"Complete the sentence",body:"你不是会说中文吗？___",options:["那我教你说中文吧","那你来跟他说吧","那你快去学中文吧","那你一句也不会吗"],answer:1,explain:"“你不是会说中文吗”意思是“你会说中文”，所以让他去说。",explainEn:'不是…吗 here means "you CAN speak Chinese", so you should talk to him.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我们不是说好了七点见吗？","你不是已经吃饭了呢？","你不是喜欢喝咖啡吗？","今天不是星期六吗？"],answer:1,explain:"反问句“不是……吗”要用“吗”，不能用“呢”，应改为“你不是已经吃饭了吗？”。",explainEn:"This rhetorical pattern ends in 吗, not 呢."},{q:"翻译：Isn't your sister a doctor?",a:"你姐姐不是医生吗？",instr:"翻译",instrEn:"Translate",body:"Isn't your sister a doctor?"}],note:"形式是问句，但常常不是为了得到新信息，而是强调说话人的判断。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"bùshì + Sentence + ma? (rhetorical question: 'isn't it...?')",noteEn:"It's a question in form but stresses the speaker's judgement, not new info.",typeEn:"Rhetorical question"},{id:"NH3.17.3",name:"递进复句“……，更……”",pinyin:"... gèng ...",type:"递进复句",explainEn:"Use 更 in the second part to add a stronger or higher-degree point: “even more”.",structure:"A，B + 更 + 形容词/动词",examples:[{zh:"这本书很好，那本书更有意思。",en:"This book is good; that one is even more interesting.",py:"Zhè běn shū hěn hǎo, nà běn shū gèng yǒu yì si."},{zh:"白天很冷，晚上更冷。",en:"It is cold in the daytime and even colder at night.",py:"Bái tiān hěn lěng, wǎn shàng gèng lěng."},{zh:"我喜欢中文，更喜欢中文课。",en:"I like Chinese, and I like Chinese class even more.",py:"Wǒ xǐ huan zhōng wén, gèng xǐ huan zhōng wén kè."}],exercises:[{kind:"choice",q:"昨天的作业不少，今天的作业___。",instr:"辨析",instrEn:"Pick the right one",body:"昨天的作业不少，今天的作业___。",options:["多更","更很多","更多","越多"],answer:2,explain:"“更”放在形容词前面，后面不能再加“很”；“越”要前后一起用。",explainEn:"更 goes before the adjective and cannot be followed by 很; 越 needs a pair."},{kind:"choice",q:"昨天已经很冷了，今天更冷，___。",instr:"完成",instrEn:"Complete the sentence",body:"昨天已经很冷了，今天更冷，___。",options:["我换上了短裤","我多穿了一件衣服","我少穿了一件衣服","我把大衣放回去了"],answer:1,explain:"“更冷”表示比昨天还冷，所以要多穿衣服。",explainEn:"更冷 means colder than yesterday, so I wear more clothes."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这个题很难，那个题更难。","坐车很快，坐地铁更快。","他喜欢看书，更喜欢写故事。","他很高，他弟弟更很高。"],answer:3,explain:"“更”和“很”不能一起用，应改为“他弟弟更高”。",explainEn:"更 and 很 can't be used together: 他弟弟更高。"},{q:"翻译：That book is even more interesting.",a:"那本书更有意思。",instr:"翻译",instrEn:"Translate",body:"That book is even more interesting."}],note:"第二部分在前一层意思上进一步加强程度。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"A, B + gèng + Adjective/Verb (even more ...)",noteEn:"The second part intensifies the degree of the first.",typeEn:"Progressive clause"},{id:"NH3.17.4",name:"条件复句“只有……，才……”",pinyin:"zhǐyǒu ... cái ...",type:"条件复句",explainEn:"Use 只有…才… to mean “only if… then…”. The first condition is necessary.",structure:"只有 + 必要条件，才 + 结果",examples:[{zh:"只有多练习，中文才会进步。",en:"Only with more practice will your Chinese improve.",py:"Zhǐ yǒu duō liàn xí, zhōng wén cái huì jìn bù."},{zh:"只有有票，才能进去。",en:"Only if you have a ticket can you go in.",py:"Zhǐ yǒu yǒu piào, cái néng jìn qù."},{zh:"只有周末，我才有时间运动。",en:"Only on weekends do I have time to exercise.",py:"Zhǐ yǒu zhōu mò, wǒ cái yǒu shí jiān yùn dòng."}],exercises:[{kind:"choice",q:"这个问题只有王老师___能回答。",instr:"辨析",instrEn:"Pick the right one",body:"这个问题只有王老师___能回答。",options:["都","才","也","就"],answer:1,explain:"“只有”提出唯一的条件，后面要用“才”；“就”要和“只要”搭配。",explainEn:"只有 gives the only condition and pairs with 才; 就 pairs with 只要."},{kind:"choice",q:"只有早点儿出发，___。",instr:"完成",instrEn:"Complete the sentence",body:"只有早点儿出发，___。",options:["我们才能早点儿到","我们才会晚到","我们就会晚到","我们才不会早到"],answer:0,explain:"“只有……才……”说必须有的条件和它带来的结果：早出发才能早到；“就”不能和“只有”搭配。",explainEn:"只有…才… links a necessary condition to its result: leave early, then arrive early; 就 does not pair with 只有."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["只有认真复习，才能考好。","只有天气好，我们才去爬山。","只有她才知道这件事。","只有你来，我们就开始。"],answer:3,explain:"“只有”要和“才”搭配，应改为“只有你来，我们才开始”。",explainEn:"只有 pairs with 才: 只有你来，我们才开始。"},{q:"翻译：Only if you finish your homework can you watch TV.",a:"只有写完作业，你才能看电视。",instr:"翻译",instrEn:"Translate",body:"Only if you finish your homework can you watch TV."}],note:"“只有”提出必须满足的条件；没有这个条件，后面的结果通常不能发生。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"zhǐyǒu + Necessary Condition, cái + Result (only if..., then...)",noteEn:"只有 gives a necessary condition; without it, the result can't happen.",typeEn:"Conditional"}]},{num:18,title:"我学会了包饺子",points:[{id:"NH3.18.1",name:"概数表达法",pinyin:"gàishù biǎodáfǎ",type:"概数表达",explainEn:"Use nearby numbers or words such as 来/左右 to give an approximate number.",structure:"相邻数字 + 量词；数量 + 来/左右",examples:[{zh:"我等了两三分钟。",en:"I waited for two or three minutes.",py:"Wǒ děng le liǎng sān fēn zhōng."},{zh:"教室里有三四十个人。",en:"There are about thirty or forty people in the classroom.",py:"Jiào shì lǐ yǒu sān sì shí ge rén."},{zh:"他三十岁左右。",en:"He is around thirty years old.",py:"Tā sān shí suì zuǒ yòu."}],exercises:[{kind:"choice",q:"我们班学生不多，只有___学生。",instr:"辨析",instrEn:"Pick the right one",body:"我们班学生不多，只有___学生。",options:["二十个来","二十左右个","二十来个","二十个多"],answer:2,explain:"“来、多”要放在数词后、量词前，如“二十来个、二十多个”；“左右”要放在“个学生”后面。",explainEn:"来 and 多 go between the number and the measure word (二十来个); 左右 goes after the whole phrase."},{kind:"choice",q:"这件衣服两百块左右，___。",instr:"完成",instrEn:"Complete the sentence",body:"这件衣服两百块左右，___。",options:["可能只要五十块","可能要一千块","可能是一百九十八块","可能是四百块"],answer:2,explain:"“左右”表示比这个数多一点儿或少一点儿，一百九十八块最接近两百块。",explainEn:"左右 means a little more or less than the number; 198 is closest to 200."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["教室里有二十来个人。","这件衣服一百块左右。","我等了他十左右分钟。","我每天睡七八个小时。"],answer:2,explain:"“左右”要放在数量词后面，应改为“我等了他十分钟左右”。",explainEn:"左右 goes after the number + measure phrase: 十分钟左右."},{q:"翻译：about thirty or forty people",a:"三四十个人",instr:"翻译",instrEn:"Translate",body:"about thirty or forty people"}],note:"概数表示大概数量。本级重点复习相邻数字连用，并理解“来、左右”等常见约数形式。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"Adjacent numbers + Measure Word; Quantity + lái/zuǒyòu (approximate number)",noteEn:"Approximate numbers: review adjacent-number pairs and forms like 来/左右.",typeEn:"Approx. number"},{id:"NH3.18.2",name:"“刚才”和“刚刚”",pinyin:"gāngcái hé gānggāng",type:"时间表达",explainEn:"Both mean “just now”. 刚才 is a time noun; 刚刚 is an adverb and stays close to the verb.",structure:"刚才 + 句子；主语 + 刚刚 + 动词",examples:[{zh:"刚才老师给我打电话了。",en:"The teacher called me just now.",py:"Gāng cái lǎo shī gěi wǒ dǎ diàn huà le."},{zh:"我刚刚到家。",en:"I just got home.",py:"Wǒ gāng gāng dào jiā."},{zh:"刚才你去哪儿了？",en:"Where did you go just now?",py:"Gāng cái nǐ qù nǎr le?"}],exercises:[{kind:"choice",q:"我___到北京两天，还不认识路。",instr:"辨析",instrEn:"Pick the right one",body:"我___到北京两天，还不认识路。",options:["刚才","马上","刚刚","以前"],answer:2,explain:"“刚刚”是副词，放在动词前，后面可以说时间段“两天”；“刚才”只指几分钟前，不能和“两天”一起用。",explainEn:"刚刚 is an adverb and can take a time span (two days); 刚才 means a few minutes ago."},{kind:"choice",q:"刚才还是晴天，___。",instr:"完成",instrEn:"Complete the sentence",body:"刚才还是晴天，___。",options:["现在下雨了","上个月一直下雨","明天可能下雨","一直没下过雨"],answer:0,explain:"“刚才”指说话前不久，和“现在”的情况对比，所以是“现在下雨了”。",explainEn:"刚才 means a moment ago, contrasted with now: now it's raining."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我刚刚吃完饭。","他刚才来了这里三天。","刚才谁来过？","刚才你说什么了？"],answer:1,explain:"“刚才”只指说话前不久，不能和“三天”一起用，应改为“他刚刚来这里三天”。",explainEn:`刚才 means a moment ago and can't go with "three days"; use 刚刚.`},{q:"翻译：I just finished my homework.",a:"我刚刚写完作业。",instr:"翻译",instrEn:"Translate",body:"I just finished my homework."}],note:"“刚才”可以单独作时间成分；“刚刚”是副词，通常放在动词前。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"gāngcái + Sentence; Subject + gānggāng + Verb",noteEn:"刚才 can stand as a time word; 刚刚 is an adverb, usually before the verb.",typeEn:"Time"},{id:"NH3.18.3",name:"条件复句“只要……，就……”",pinyin:"zhǐyào ... jiù ...",type:"条件复句",explainEn:"Use 只要…就… to mean “as long as… then…”.",structure:"只要 + 条件，就 + 结果",examples:[{zh:"只要你努力，就会进步。",en:"As long as you work hard, you will improve.",py:"Zhǐ yào nǐ nǔ lì, jiù huì jìn bù."},{zh:"只要不下雨，我们就去。",en:"As long as it does not rain, we will go.",py:"Zhǐ yào bù xià yǔ, wǒ men jiù qù."},{zh:"只要有时间，我就练习中文。",en:"As long as I have time, I practice Chinese.",py:"Zhǐ yào yǒu shí jiān, wǒ jiù liàn xí zhōng wén."}],exercises:[{kind:"choice",q:"只要你喜欢，我___送给你。",instr:"辨析",instrEn:"Pick the right one",body:"只要你喜欢，我___送给你。",options:["就","才","也","还"],answer:0,explain:"“只要”表示有这个条件就够了，后面用“就”；“才”要和“只有”搭配。",explainEn:"只要 pairs with 就; 才 pairs with 只有."},{kind:"choice",q:"只要你多看中文电影，___。",instr:"完成",instrEn:"Complete the sentence",body:"只要你多看中文电影，___。",options:["中文才会越来越好","中文就会越来越差","中文就会越来越好","中文都会越来越好"],answer:2,explain:"“只要”表示有这个条件就够了，后面用“就”，多看电影会让中文变好；“才”要和“只有”搭配。",explainEn:"只要 pairs with 就: watching films is enough to make your Chinese better; 才 pairs with 只有."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["只要不下雨，比赛就开始。","只要多练习，才能说好中文。","只要有手机，就能买票。","只要你来，我就很高兴。"],answer:1,explain:"“只要”要和“就”搭配，应改为“只要多练习，就能说好中文”。",explainEn:"只要 pairs with 就: 只要多练习，就能说好中文。"},{q:"翻译：As long as you are happy, I'm happy too.",a:"只要你高兴，我就高兴。",instr:"翻译",instrEn:"Translate",body:"As long as you are happy, I'm happy too."}],note:"“只要”表示这个条件一满足，后面的结果就能够发生。和“只有……才……”要注意区分。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"zhǐyào + Condition, jiù + Result (as long as..., then...)",noteEn:"只要: once met, the result can happen—distinguish from 只有…才….",typeEn:"Conditional"},{id:"NH3.18.4",name:"固定格式“从……起”",pinyin:"cóng ... qǐ",type:"时间/起点结构",explainEn:"Use 从…起 to mean “starting from… / from…on”.",structure:"从 + 时间/地点 + 起",examples:[{zh:"从明天起，我每天早起。",en:"Starting tomorrow, I will get up early every day.",py:"Cóng míng tiān qǐ, wǒ měi tiān zǎo qǐ."},{zh:"从下个月起，我们换新教室。",en:"Starting next month, we will use a new classroom.",py:"Cóng xià ge yuè qǐ, wǒ men huàn xīn jiào shì."},{zh:"从这里起，一直往前走。",en:"Starting from here, keep walking forward.",py:"Cóng zhè lǐ qǐ, yì zhí wǎng qián zǒu."}],exercises:[{kind:"choice",q:"___今天起，我不喝咖啡了。",instr:"辨析",instrEn:"Pick the right one",body:"___今天起，我不喝咖啡了。",options:["从","离","在","到"],answer:0,explain:"“从……起”表示从某个时间开始，前面要用“从”。",explainEn:'从…起 means "starting from"; it needs 从.'},{kind:"choice",q:"从下个星期起，___。",instr:"完成",instrEn:"Complete the sentence",body:"从下个星期起，___。",options:["我们每天八点上课","上星期我们不上课","我们已经放假了","我们昨天开始上课"],answer:0,explain:"“从下个星期起”说的是以后开始的情况，后面不能说昨天、上星期的事。",explainEn:"从下个星期起 starts in the future, so the rest can't be about the past."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["从这个周末起，我开始学游泳。","从那天起，他再也没迟到过。","到今天起，我每天锻炼。","从这个学期起，我们有新老师了。"],answer:2,explain:"表示开始的时间要用“从……起”，应改为“从今天起，我每天锻炼”。",explainEn:"A starting point uses 从…起: 从今天起，我每天锻炼。"},{q:"翻译：Starting today, I will read every day.",a:"从今天起，我每天看书。",instr:"翻译",instrEn:"Translate",body:"Starting today, I will read every day."}],note:"“从……起”强调一个新的时间或空间起点。",source:"https://www.cypressbooks.com/samples/9787521368031.pdf",structureEn:"cóng + Time/Place + qǐ (starting from ...)",noteEn:"从…起 stresses a new starting point in time or space.",typeEn:"Time / Starting point"}]}],i={series:e,unit:3,lessons:n};export{i as default,n as lessons,e as series,t as unit};
